/**
 * Track layouts — data only.
 *
 * Author a circuit as a closed polygon of [x, z, filletR] verts, or call
 * `makeSeedLayout(seed)` for a procedural variant. Pass the result to
 * `new Track(layout)`. Fillet radii stay in metres (boat turning circle);
 * XZ is scaled by `layoutScale`.
 *
 * Rules of thumb:
 *   · filletR ≥ CONFIG.race.deckHalf (~16) or the ribbon self-intersects
 *   · filletR < ~50 for a real brake corner (else flat-out)
 *   · keep straights between fillets ≥ ~6 m after tan-length subtraction
 */

import { CONFIG } from '../core/config';

/** One polygon vertex: world XZ (pre-scale) + fillet radius in metres. */
export type TrackVertex = readonly [x: number, z: number, filletR: number];

export type SeedLength = 'short' | 'medium' | 'long';
export type SeedStyle = 'flow' | 'mixed' | 'tech';
export type SeedShape = 'oval' | 'organic' | 'twisty';
export type SeedRelief = 'flat' | 'rolling' | 'hilly';
export type SeedWidth = 'tight' | 'normal' | 'wide';
export type SeedBanks = 'easy' | 'mixed' | 'hard';
export type SeedGates = 'few' | 'normal' | 'many';

/** Options for `makeSeedLayout` — driven by the title-screen generator. */
export type SeedLayoutOpts = {
  verts?: number;
  layoutScale?: number;
  startS?: number;
  gateCount?: number;
  /** Lap footprint / vert count. Default medium. */
  length?: SeedLength;
  /** Corner density. Default mixed. */
  style?: SeedStyle;
  /** Plan silhouette family. Default organic. */
  shape?: SeedShape;
  /** Deck elevation drama. Default rolling. */
  relief?: SeedRelief;
  /** Corridor scale (tight sprint ↔ wide stadium). Default normal. */
  width?: SeedWidth;
  /** Hairpin / chicane aggression. Default mixed. */
  banks?: SeedBanks;
  /** Arch gate count band. Default normal. */
  gates?: SeedGates;
};

export type TrackLayout = {
  /** Stable id for URL / layout pick (`?track=canyon`). */
  id: string;
  /** Short label for HUD / menus. */
  name: string;
  /** Closed polygon in travel order. */
  verts: readonly TrackVertex[];
  /** Scales XZ only — radii stay boat-relative. Default 0.7. */
  layoutScale?: number;
  /** Start/finish offset along the first straight after V0 (m). Default 88. */
  startS?: number;
  /** Arch gates around the lap. Default 12. */
  gateCount?: number;
  /** Deck elevation intensity from the generator. */
  relief?: SeedRelief;
  /** Optional extras (legacy; generation no longer creates loops). */
  features?: TrackFeatures;
};

/** Sparse extras — kept for older layouts; generator no longer emits loops. */
export type TrackFeatures = {
  /** Legacy vertical loop markers (ignored by new seeds). */
  loops?: readonly { u: number; radius: number }[];
};

export const DEFAULT_LAYOUT_SCALE = 0.7;
export const DEFAULT_START_S = 88;
export const DEFAULT_GATE_COUNT = 12;

