/** Menu order for the course picker (Canyon is the default). */
export const SHIPPED_LAYOUT_IDS = ['canyon', 'oval', 'sprint'] as const;
export type ShippedLayoutId = (typeof SHIPPED_LAYOUT_IDS)[number];

export const DEFAULT_LAYOUT = CANYON_LAYOUT;

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function angleDelta(a: number, b: number): number {
  let d = b - a;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  return d;
}

type Pt = { x: number; z: number };

/** Cross product (b−a)×(c−a) in XZ — sign is winding. */
function cross(ax: number, az: number, bx: number, bz: number, cx: number, cz: number) {
  return (bx - ax) * (cz - az) - (bz - az) * (cx - ax);
}

/** True if segments AB and CD properly intersect (not just shared endpoints). */
function segmentsCross(
  ax: number,
  az: number,
  bx: number,
  bz: number,
  cx: number,
  cz: number,
  dx: number,
  dz: number,
): boolean {
  const d1 = cross(ax, az, bx, bz, cx, cz);
  const d2 = cross(ax, az, bx, bz, dx, dz);
  const d3 = cross(cx, cz, dx, dz, ax, az);
  const d4 = cross(cx, cz, dx, dz, bx, bz);
  // Collinear / touching endpoint cases — ignore (common on closed rings).
  if (d1 === 0 || d2 === 0 || d3 === 0 || d4 === 0) return false;
  return (d1 > 0) !== (d2 > 0) && (d3 > 0) !== (d4 > 0);
}

/** Closed polyline self-intersects (non-adjacent edges). */
function polygonSelfIntersects(pts: Pt[]): boolean {
  const n = pts.length;
  for (let i = 0; i < n; i++) {
    const a = pts[i]!;
    const b = pts[(i + 1) % n]!;
    for (let j = i + 1; j < n; j++) {
      if (Math.abs(i - j) <= 1 || (i === 0 && j === n - 1)) continue;
      // Skip adjacent legs that share a vertex.
      if ((j + 1) % n === i) continue;
      const c = pts[j]!;
      const d = pts[(j + 1) % n]!;
      if (segmentsCross(a.x, a.z, b.x, b.z, c.x, c.z, d.x, d.z)) return true;
    }
  }
  return false;
}

/** Minimum chord length around the ring. */
function minChord(pts: Pt[]): number {
  let m = Infinity;
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i]!;
    const b = pts[(i + 1) % pts.length]!;
    m = Math.min(m, Math.hypot(b.x - a.x, b.z - a.z));
  }
  return m;
}

/**
 * Push verts apart until chords clear `minLen` (keeps complex shapes rideable).
 */
function separateChords(pts: Pt[], minLen: number, passes = 6): void {
  const n = pts.length;
  for (let p = 0; p < passes; p++) {
    for (let i = 0; i < n; i++) {
      const a = pts[i]!;
      const b = pts[(i + 1) % n]!;
      const dx = b.x - a.x;
      const dz = b.z - a.z;
      const len = Math.hypot(dx, dz) || 1e-6;
      if (len >= minLen) continue;
      const push = (minLen - len) * 0.5;
      const ux = dx / len;
      const uz = dz / len;
      a.x -= ux * push;
      a.z -= uz * push;
      b.x += ux * push;
      b.z += uz * push;
    }
  }
}

/**
 * Build a multi-lobe closed ring: harmonics + pinches.
 * `size` scales the plan footprint (1 = medium).
 */
function buildComplexRing(rng: () => number, n: number, size = 1): Pt[] {
  const rx = (300 + rng() * 180) * size;
  const rz = (260 + rng() * 160) * size;
  // 2–4 radial lobes so the plan reads as bays / headlands, not an oval.
  const lobes = 2 + Math.floor(rng() * 3);
  const lobeAmp = 0.22 + rng() * 0.32;
  const lobePhase = rng() * Math.PI * 2;
  const fineAmp = 0.08 + rng() * 0.14;
  const fineFreq = 5 + Math.floor(rng() * 5);
  const finePhase = rng() * Math.PI * 2;
  // Occasional hard pinch (narrow waist) for a figure-8-ish read without crossing.
  const pinchA = rng() * Math.PI * 2;
  const pinchW = 0.4 + rng() * 0.5;
  const pinchDepth = 0.14 + rng() * 0.2;
  // Asymmetric stretch — one half of the lap is wider.
  const biasA = rng() * Math.PI * 2;
  const biasAmp = 0.08 + rng() * 0.12;

  const pts: Pt[] = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    let r =
      1 +
      lobeAmp * Math.cos(lobes * a + lobePhase) +
      fineAmp * Math.cos(fineFreq * a + finePhase) +
      biasAmp * Math.cos(a + biasA);
    const da = angleDelta(a, pinchA);
    if (Math.abs(da) < pinchW) {
      const t = 1 - Math.abs(da) / pinchW;
      r -= pinchDepth * t * t;
    }
    r = Math.max(0.48, r);
    // Tangential jitter invents chicane kinks without leaving the ring family.
    const tang = (rng() - 0.5) * (22 + rng() * 40);
    const nx = Math.sin(a);
    const nz = Math.cos(a);
    const tx = nz;
    const tz = -nx;
    pts.push({
      x: nx * rx * r + tx * tang,
      z: nz * rz * r + tz * tang,
    });
  }

  separateChords(pts, 75, 8);
  return pts;
}

/**
 * Simple elongated stadium — long straights, gentle corners.
 */
function buildStadiumRing(rng: () => number, size = 1): Pt[] {
  const rx = (380 + rng() * 40) * size;
  const rz = (220 + rng() * 30) * size;
  const n = 8;
  const pts: Pt[] = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const squash = 0.92 + 0.08 * Math.abs(Math.cos(a));
    pts.push({
      x: Math.sin(a) * rx * squash,
      z: Math.cos(a) * rz,
    });
  }
  separateChords(pts, 90 * size, 4);
  return pts;
}

/**
 * Extra-lobed ring for twisty generation.
 */
function buildTwistyRing(rng: () => number, n: number, size = 1): Pt[] {
  const rx = (280 + rng() * 120) * size;
  const rz = (240 + rng() * 100) * size;
  const lobes = 4 + Math.floor(rng() * 3);
  const lobeAmp = 0.34 + rng() * 0.28;
  const lobePhase = rng() * Math.PI * 2;
  const fineAmp = 0.12 + rng() * 0.12;
  const fineFreq = 7 + Math.floor(rng() * 4);
  const finePhase = rng() * Math.PI * 2;
  const pts: Pt[] = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    let r =
      1 +
      lobeAmp * Math.cos(lobes * a + lobePhase) +
      fineAmp * Math.cos(fineFreq * a + finePhase);
    r = Math.max(0.45, r);
    const tang = (rng() - 0.5) * (30 + rng() * 50);
    const nx = Math.sin(a);
    const nz = Math.cos(a);
    pts.push({
      x: nx * rx * r + nz * tang,
      z: nz * rz * r - nx * tang,
    });
  }
  separateChords(pts, 68, 8);
  return pts;
}

/** Dive a hairpin pocket inward at index `at`. Returns null if the result knots. */
function tryHairpin(pts: Pt[], at: number, rng: () => number): Pt[] | null {
  const n = pts.length;
  const i = ((at % n) + n) % n;
  const prev = pts[(i - 1 + n) % n]!;
  const next = pts[(i + 1) % n]!;
  const mx = (prev.x + next.x) * 0.5;
  const mz = (prev.z + next.z) * 0.5;
  const ix = -mx;
  const iz = -mz;
  const il = Math.hypot(ix, iz) || 1;
  const depth = 70 + rng() * 90;
  const side = 32 + rng() * 40;
  const sx = -iz / il;
  const sz = ix / il;
  const tip = { x: mx + (ix / il) * depth, z: mz + (iz / il) * depth };
  const wingA = {
    x: tip.x + sx * side * 0.5 - (ix / il) * 18,
    z: tip.z + sz * side * 0.5 - (iz / il) * 18,
  };
  const wingB = {
    x: tip.x - sx * side * 0.5 - (ix / il) * 18,
    z: tip.z - sz * side * 0.5 - (iz / il) * 18,
  };
  const out = pts.slice();
  out.splice(i, 1, wingA, tip, wingB);
  separateChords(out, 68, 6);
  if (polygonSelfIntersects(out) || minChord(out) < 52) return null;
  return out;
}

/** Opposite lateral shove on two consecutive verts — a chicane. */
function tryChicane(pts: Pt[], at: number, rng: () => number): Pt[] | null {
  const n = pts.length;
  const i = ((at % n) + n) % n;
  const out = pts.map((p) => ({ x: p.x, z: p.z }));
  const a = out[i]!;
  const b = out[(i + 1) % n]!;
  const dx = b.x - a.x;
  const dz = b.z - a.z;
  const len = Math.hypot(dx, dz) || 1;
  const px = -dz / len;
  const pz = dx / len;
  const amp = 48 + rng() * 55;
  a.x += px * amp;
  a.z += pz * amp;
  b.x -= px * amp;
  b.z -= pz * amp;
  separateChords(out, 68, 5);
  if (polygonSelfIntersects(out) || minChord(out) < 52) return null;
  return out;
}

function vertsFromRing(rotated: Pt[], minR: number, rng: () => number): TrackVertex[] {
  const n = rotated.length;
  const verts: TrackVertex[] = [];
  for (let i = 0; i < n; i++) {
    const prev = rotated[(i - 1 + n) % n]!;
    const cur = rotated[i]!;
    const next = rotated[(i + 1) % n]!;
    const h0 = Math.atan2(cur.x - prev.x, cur.z - prev.z);
    const h1 = Math.atan2(next.x - cur.x, next.z - cur.z);
    const turn = Math.abs(angleDelta(h0, h1));
    const t = turn / Math.PI;
    let r: number;
    if (t > 0.5) r = minR + rng() * 2.5;
    else if (t > 0.28) r = minR + 3 + (1 - t) * 12 + rng() * 4;
    else if (t > 0.14) r = minR + 8 + (1 - t) * 18 + rng() * 5;
    else r = minR + 14 + (1 - t) * 22 + rng() * 6;
    verts.push([cur.x, cur.z, Math.min(52, Math.max(minR, r))]);
  }
  return verts;
}

function rotateLongestStart(pts: Pt[]): Pt[] {
  let best = 0;
  let bestLen = 0;
  for (let i = 0; i < pts.length; i++) {
    const j = (i + 1) % pts.length;
    const len = Math.hypot(pts[j]!.x - pts[i]!.x, pts[j]!.z - pts[i]!.z);
    if (len > bestLen) {
      bestLen = len;
      best = i;
    }
  }
  return pts.slice(best).concat(pts.slice(0, best));
}

/**
 * Procedural closed circuit from a seed.
 * Length / style / shape / relief / width / banks / gates from `opts`.
 */
export function makeSeedLayout(seed: number, opts?: SeedLayoutOpts): TrackLayout {
  const rng = mulberry32(seed >>> 0);
  const minR = CONFIG.race.deckHalf + 2;
  const length = opts?.length ?? 'medium';
  const style = opts?.style ?? 'mixed';
  const shape = opts?.shape ?? 'organic';
  const relief = opts?.relief ?? 'rolling';
  const width = opts?.width ?? 'normal';
  const banks = opts?.banks ?? 'mixed';
  const gates = opts?.gates ?? 'normal';

  const size = length === 'short' ? 0.72 : length === 'long' ? 1.28 : 1;
  const targetN = Math.max(
    10,
    Math.min(
      17,
      opts?.verts ??
        (shape === 'oval'
          ? 8
          : length === 'short'
            ? 10 + Math.floor(rng() * 2)
            : length === 'long'
              ? 14 + Math.floor(rng() * 3)
              : 12 + Math.floor(rng() * 3)),
    ),
  );

  const widthScale =
    width === 'tight' ? 0.82 : width === 'wide' ? 1.18 : 1;
  let defaultScale =
    (length === 'short' ? 0.5 + rng() * 0.08 : length === 'long' ? 0.72 + rng() * 0.12 : 0.58 + rng() * 0.14) *
    widthScale;
  if (shape === 'oval') defaultScale = (0.7 + rng() * 0.1) * widthScale;

  let pts: Pt[] = [];
  if (shape === 'oval') {
    pts = buildStadiumRing(rng, size);
  } else {
    const builder = shape === 'twisty' ? buildTwistyRing : buildComplexRing;
    for (let attempt = 0; attempt < 5; attempt++) {
      const candidate = builder(rng, targetN - (attempt > 2 ? 1 : 0), size);
      if (!polygonSelfIntersects(candidate) && minChord(candidate) >= 55 * size) {
        pts = candidate;
        break;
      }
    }
    if (pts.length < 7) pts = buildStadiumRing(rng, size);
  }

  // Banks: hairpin / chicane chances (style still biases tech vs flow).
  const styleH = style === 'tech' ? 1.25 : style === 'flow' ? 0.55 : 1;
  const styleC = style === 'tech' ? 1.2 : style === 'flow' ? 0.5 : 1;
  const hairpinChance =
    banks === 'easy' ? 0.08 * styleH : banks === 'hard' ? 0.9 * styleH : 0.5 * styleH;
  const chicaneChance =
    banks === 'easy' ? 0.06 * styleC : banks === 'hard' ? 0.85 * styleC : 0.45 * styleC;
  const hairpinTries = banks === 'hard' ? 2 : 1;
  const chicaneTries = banks === 'hard' ? 2 : 1;

  if (shape !== 'oval') {
    for (let t = 0; t < hairpinTries; t++) {
      if (rng() >= Math.min(0.95, hairpinChance)) continue;
      const at = 2 + Math.floor(rng() * Math.max(1, pts.length - 4));
      const next = tryHairpin(pts, at, rng);
      if (next) pts = next;
    }
    for (let t = 0; t < chicaneTries; t++) {
      if (rng() >= Math.min(0.95, chicaneChance)) continue;
      const at = 1 + Math.floor(rng() * Math.max(1, pts.length - 3));
      const next = tryChicane(pts, at, rng);
      if (next) pts = next;
    }
  }

  if (polygonSelfIntersects(pts)) {
    pts = buildStadiumRing(rng, size);
  }

  const rotated = rotateLongestStart(pts);
  const verts = vertsFromRing(rotated, minR, rng);
  const n = verts.length;
  const cornerCount = verts.filter(([, , r]) => r < minR + 8).length;

  const gateCount =
    opts?.gateCount ??
    (gates === 'few'
      ? 8
      : gates === 'many'
        ? Math.min(16, 12 + Math.floor(n * 0.35))
        : Math.min(14, Math.max(9, 8 + Math.floor(n * 0.45))));

  let name: string;
  if (shape === 'oval') name = `Oval ${seed >>> 0}`;
  else if (style === 'tech' || banks === 'hard' || cornerCount >= 4) name = `Tech ${seed >>> 0}`;
  else if (style === 'flow' || banks === 'easy') name = `Flow ${seed >>> 0}`;
  else if (shape === 'twisty') name = `Twist ${seed >>> 0}`;
  else name = `Gen ${seed >>> 0}`;

  return {
    id: `seed-${seed >>> 0}`,
    name,
    layoutScale: opts?.layoutScale ?? defaultScale,
    startS: opts?.startS ?? 45 + Math.floor(rng() * 50),
    gateCount,
    relief,
    verts,
  };
}

/** Author helper — clone verts with a uniform fillet floor. */
export function layoutFromVerts(
  id: string,
  name: string,
  verts: readonly TrackVertex[],
  opts?: Omit<TrackLayout, 'id' | 'name' | 'verts'>,
): TrackLayout {
  const minR = CONFIG.race.deckHalf + 1;
  return {
    id,
    name,
    layoutScale: opts?.layoutScale ?? DEFAULT_LAYOUT_SCALE,
    startS: opts?.startS ?? DEFAULT_START_S,
    gateCount: opts?.gateCount ?? DEFAULT_GATE_COUNT,
    relief: opts?.relief,
    verts: verts.map(([x, z, r]) => [x, z, Math.max(minR, r)] as const),
  };
}

/**
 * Resolve a layout from an id (`canyon`), seed token (`seed-42`),
 * or a full `TrackLayout` object.
 */
export function resolveLayout(spec?: string | TrackLayout | null): TrackLayout {
  if (!spec) return DEFAULT_LAYOUT;
  if (typeof spec !== 'string') {
    return spec.verts?.length >= 3 ? spec : DEFAULT_LAYOUT;
  }
  const key = spec.trim().toLowerCase();
  if (LAYOUTS[key]) return LAYOUTS[key]!;
  // Legacy coaster ids → plain seed (looping removed from generation).
  const coasterMatch = /^coaster[-:](\d+)$/.exec(key);
  if (coasterMatch) return makeSeedLayout(Number(coasterMatch[1]), { shape: 'oval' });
  const seedMatch = /^seed[-:](\d+)$/.exec(key);
  if (seedMatch) return makeSeedLayout(Number(seedMatch[1]));
  if (/^\d+$/.test(key)) return makeSeedLayout(Number(key));
  console.warn(`[track] unknown layout "${spec}", falling back to canyon`);
  return DEFAULT_LAYOUT;
}

/** Read `?track=` from the page URL (client-only). */
export function layoutFromUrl(search = typeof location !== 'undefined' ? location.search : ''): TrackLayout {
  const q = new URLSearchParams(search);
  return resolveLayout(q.get('track'));
}
