/**
 * Soft driving assists for touch / mobile play.
 * Keeps the craft pointed along the ribbon when the thumb is mostly idle,
 * and forgives mild off-track mistakes.
 */

import { Vector3 } from 'three';
import { CONFIG } from './config';
import { clamp } from './mathx';
import type { ShipState, TrackAPI, TrackPoint } from './types';

const _tp: TrackPoint = {
  position: new Vector3(),
  tangent: new Vector3(0, 0, 1),
  curvature: 0,
  u: 0,
};

/** Gentle heading pull toward track tangent when not steering hard. */
export function applyMobileSteerAssist(
  state: ShipState,
  track: TrackAPI,
  steerInput: number,
  dt: number,
) {
  const speed = Math.hypot(state.velocity.x, state.velocity.z);
  if (speed < 4) return;

  const proj = track.project(state.position);
  track.sample(proj.u, _tp);
  const tx = _tp.tangent.x;
  const tz = _tp.tangent.z;
  const tLen = Math.hypot(tx, tz) || 1;
  const want = Math.atan2(tx / tLen, tz / tLen);

  let err = want - state.heading;
  while (err > Math.PI) err -= Math.PI * 2;
  while (err < -Math.PI) err += Math.PI * 2;

  // Stronger help when nearly straight / wrong-way; backs off under player steer.
  const idle = 1 - Math.min(1, Math.abs(steerInput) / 0.55);
  const wrong = Math.cos(err) < 0 ? 1.35 : 1;
  const rate = (1.15 + speed * 0.008) * idle * wrong;
  state.heading += clamp(err, -0.9, 0.9) * Math.min(1, rate * dt);

  // Soft centreline pull when drifting off the deck with little steer input.
  const lat = proj.lateral;
  const deck = CONFIG.race.deckHalf;
  if (Math.abs(lat) > deck * 0.55 && idle > 0.4) {
    const rightX = tz / tLen;
    const rightZ = -tx / tLen;
    const pull = -Math.sign(lat) * idle * 6.5 * dt;
    state.velocity.x += rightX * pull;
    state.velocity.z += rightZ * pull;
  }
}

/** Extra yaw authority + softer off-track for assisted craft. */
export const MOBILE_ASSIST = {
  /** Slightly less yaw than desktop — thumb input already feels hot. */
  turnMul: 0.92,
  offTrackDragMul: 0.55,
  offTrackThrustFloor: 0.55,
  startBoostMeter: 0.7,
  /** Auto airbrake yaw contribution (desktop Q/E uses full ±0.85). */
  airbrakeSteer: 0.45,
} as const;
