/**
 * Input. Keyboard → analogue struct shared by player and AI.
 */

export interface InputState {
  /** -1 … +1 */
  steer: number;
  /** 0 … 1 */
  throttle: number;
  /** 0 … 1 airbrake / reverse */
  brake: number;
  /** Left airbrake held (Wipeout-style). */
  airbrakeL: boolean;
  /** Right airbrake held. */
  airbrakeR: boolean;
  /** Boost held. */
  boost: boolean;
  startPressed: boolean;
  restartPressed: boolean;
  cameraTogglePressed: boolean;
  firePressed: boolean;
  /** One-shot nitro ignite (WaveKill N). */
  nitroPressed: boolean;
}

export function createInputState(): InputState {
  return {
    steer: 0,
    throttle: 0,
    brake: 0,
    airbrakeL: false,
    airbrakeR: false,
    boost: false,
    startPressed: false,
    restartPressed: false,
    cameraTogglePressed: false,
    firePressed: false,
    nitroPressed: false,
  };
}

const KEYS = {
  left: ['ArrowLeft', 'KeyA'],
  right: ['ArrowRight', 'KeyD'],
  fwd: ['ArrowUp', 'KeyW'],
  back: ['ArrowDown', 'KeyS'],
  airL: ['KeyQ', 'Comma'],
  airR: ['KeyE', 'Period'],
  boost: ['ShiftLeft', 'ShiftRight', 'Space'],
  start: ['Enter'],
  restart: ['KeyR'],
  camera: ['KeyC'],
  fire: ['KeyF', 'ControlLeft', 'ControlRight'],
  nitro: ['KeyN'],
};

export class InputManager {
  readonly state = createInputState();
  private down = new Set<string>();
  private pressedThisFrame = new Set<string>();
  private steerSmooth = 0;

  constructor(private target: EventTarget = window) {
    target.addEventListener('keydown', this.onKeyDown);
    target.addEventListener('keyup', this.onKeyUp);
    target.addEventListener('blur', this.onBlur);
  }

  private onKeyDown = (ev: Event) => {
    const e = ev as KeyboardEvent;
    if (e.repeat) return;
    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();
    this.down.add(e.code);
    this.pressedThisFrame.add(e.code);
  };
  private onKeyUp = (ev: Event) => {
    this.down.delete((ev as KeyboardEvent).code);
  };
  private onBlur = () => {
    this.down.clear();
  };

  private any(codes: string[]) {
    for (const c of codes) if (this.down.has(c)) return true;
    return false;
  }
  private anyPressed(codes: string[]) {
    for (const c of codes) if (this.pressedThisFrame.has(c)) return true;
    return false;
  }

  update(dt: number) {
    const left = this.any(KEYS.left) ? -1 : 0;
    const right = this.any(KEYS.right) ? 1 : 0;
    const target = left + right;
    const rate = target === 0 ? 14 : 18;
    this.steerSmooth += (target - this.steerSmooth) * Math.min(1, rate * dt);

    this.state.steer = this.steerSmooth;
    this.state.throttle = this.any(KEYS.fwd) ? 1 : 0;
    this.state.brake = this.any(KEYS.back) ? 1 : 0;
    this.state.airbrakeL = this.any(KEYS.airL);
    this.state.airbrakeR = this.any(KEYS.airR);
    this.state.boost = this.any(KEYS.boost);
    this.state.startPressed = this.anyPressed(KEYS.start) || this.anyPressed(KEYS.boost);
    this.state.restartPressed = this.anyPressed(KEYS.restart);
    this.state.cameraTogglePressed = this.anyPressed(KEYS.camera);
    // Held, not edge — RocketField needs F held for lock-and-release fire.
    this.state.firePressed = this.any(KEYS.fire);
    this.state.nitroPressed = this.anyPressed(KEYS.nitro);

    this.pressedThisFrame.clear();
  }

  dispose() {
    this.target.removeEventListener('keydown', this.onKeyDown);
    this.target.removeEventListener('keyup', this.onKeyUp);
    this.target.removeEventListener('blur', this.onBlur);
  }
}
