/**
 * On-screen touch controls for mobile / coarse pointers.
 *
 * Easy layout: large left drag-zone steers (relative), right thumb gets a few
 * big actions. Airbrakes auto-engage from hard steer — no AIR pads.
 */

import { createInputState, type InputState } from './input';
import { unlockAudioSync } from '../audio/unlock';

export function prefersTouchUi(): boolean {
  if (typeof window === 'undefined') return false;
  const force = new URLSearchParams(location.search).get('touch');
  if (force === '1' || force === 'true') return true;
  if (force === '0' || force === 'false') return false;
  return (
    window.matchMedia('(pointer: coarse)').matches
    || (window.matchMedia('(hover: none)').matches && window.matchMedia('(max-width: 900px)').matches)
  );
}

function clamp(v: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, v));
}

/** Soft response — small thumb moves barely turn; full lock needs a long drag. */
function steerCurve(x: number): number {
  const ax = Math.abs(x);
  // Wider deadzone so resting thumbs don't twitch the craft.
  if (ax < 0.08) return 0;
  const t = (ax - 0.08) / 0.92;
  // Power > 1 = less mid-stick authority (was 0.6, which felt twitchy).
  return Math.sign(x) * Math.pow(t, 1.45) * 0.92;
}

type PadId = 'steer' | 'brake' | 'boost' | 'fire' | 'nitro';

type ActivePad = {
  id: PadId;
  pointerId: number;
  /** Finger X at grab — relative steer for the left zone. */
  originX: number;
};

/**
 * DOM overlay. Writes into `state` each `update()`; merge with keyboard InputManager.
 */
export class TouchControls {
  readonly state = createInputState();
  readonly active: boolean;

  private root: HTMLDivElement | null = null;
  private stickKnob: HTMLDivElement | null = null;
  private stickBase: HTMLDivElement | null = null;
  private pads = new Map<PadId, HTMLElement>();
  private activePads: ActivePad[] = [];
  private steerX = 0;
  private steerSmooth = 0;
  private nitroWas = false;
  private visible = false;

  constructor(host: HTMLElement = document.getElementById('app') ?? document.body) {
    this.active = prefersTouchUi();
    if (!this.active) return;
    this.root = this.build(host);
    this.setVisible(false);
  }

  /** Show during racing / countdown; hide on results / mode select. */
  setVisible(on: boolean) {
    if (!this.root) return;
    this.visible = on;
    this.root.style.display = on ? 'block' : 'none';
    if (!on) this.releaseAll();
  }

  update(dt: number) {
    if (!this.active || !this.visible) {
      this.clearState();
      return;
    }

    // Gentler follow so steer doesn't snap with every micro-drag.
    const rate = 7.5;
    this.steerSmooth += (this.steerX - this.steerSmooth) * Math.min(1, rate * dt);

    const brake = this.isHeld('brake');
    const boost = this.isHeld('boost');
    const fire = this.isHeld('fire');
    const nitroNow = this.isHeld('nitro');

    const steer = this.steerSmooth;
    this.state.steer = steer;
    this.state.throttle = brake ? 0 : 1;
    this.state.brake = brake ? 1 : 0;
    this.state.boost = boost;
    this.state.firePressed = fire;
    // Auto-airbrake only near full lock — mid steer must stay gentle.
    this.state.airbrakeL = steer < -0.82;
    this.state.airbrakeR = steer > 0.82;
    this.state.cameraTogglePressed = false;
    this.state.nitroPressed = nitroNow && !this.nitroWas;
    this.state.startPressed = false;
    this.state.restartPressed = false;
    this.nitroWas = nitroNow;

    this.syncKnob();
    this.syncPressedClass();
  }

  dispose() {
    this.releaseAll();
    this.root?.remove();
    this.root = null;
  }

  private clearState() {
    Object.assign(this.state, createInputState());
    this.steerX = 0;
    this.steerSmooth = 0;
    this.nitroWas = false;
  }

  private isHeld(id: PadId) {
    return this.activePads.some((p) => p.id === id);
  }

  private releaseAll() {
    this.activePads.length = 0;
    this.steerX = 0;
    this.syncKnob();
    this.syncPressedClass();
  }

  private build(host: HTMLElement): HTMLDivElement {
    const root = document.createElement('div');
    root.id = 'touch';
    root.innerHTML = `
      <div class="touch-safe">
        <div class="touch-steer-zone" data-pad="steer">
          <div class="touch-steer">
            <div class="touch-steer-ring"></div>
            <div class="touch-steer-knob"></div>
          </div>
        </div>
        <div class="touch-actions">
          <button type="button" class="touch-btn touch-boost" data-pad="boost">BOOST</button>
          <button type="button" class="touch-btn touch-fire" data-pad="fire">FIRE</button>
          <button type="button" class="touch-btn touch-brake" data-pad="brake">BRAKE</button>
          <button type="button" class="touch-btn touch-nitro" data-pad="nitro">NITRO</button>
        </div>
      </div>
    `;
    host.appendChild(root);

    this.stickBase = root.querySelector('.touch-steer') as HTMLDivElement;
    this.stickKnob = root.querySelector('.touch-steer-knob') as HTMLDivElement;
    for (const el of root.querySelectorAll<HTMLElement>('[data-pad]')) {
      const id = el.dataset.pad as PadId;
      this.pads.set(id, el);
    }

    root.addEventListener('pointerdown', this.onPointerDown, { passive: false });
    root.addEventListener('pointermove', this.onPointerMove, { passive: false });
    root.addEventListener('pointerup', this.onPointerUp, { passive: false });
    root.addEventListener('pointercancel', this.onPointerUp, { passive: false });
    root.addEventListener('lostpointercapture', this.onPointerUp);
    root.addEventListener('contextmenu', (e) => e.preventDefault());

    return root;
  }

  private onPointerDown = (ev: PointerEvent) => {
    const el = (ev.target as HTMLElement).closest('[data-pad]') as HTMLElement | null;
    if (!el || !this.root?.contains(el)) return;
    ev.preventDefault();
    unlockAudioSync();
    const id = el.dataset.pad as PadId;
    this.activePads = this.activePads.filter((p) => p.pointerId !== ev.pointerId && p.id !== id);
    this.activePads.push({ id, pointerId: ev.pointerId, originX: ev.clientX });
    try {
      el.setPointerCapture?.(ev.pointerId);
    } catch {
      /* ignore */
    }
    if (id === 'steer') this.updateSteerFromEvent(ev);
  };

  private onPointerMove = (ev: PointerEvent) => {
    const pad = this.activePads.find((p) => p.pointerId === ev.pointerId);
    if (!pad) return;
    ev.preventDefault();
    if (pad.id === 'steer') this.updateSteerFromEvent(ev);
  };

  private onPointerUp = (ev: PointerEvent) => {
    const before = this.activePads.length;
    this.activePads = this.activePads.filter((p) => p.pointerId !== ev.pointerId);
    if (this.activePads.length !== before && !this.isHeld('steer')) this.steerX = 0;
  };

  private updateSteerFromEvent(ev: PointerEvent) {
    const pad = this.activePads.find((p) => p.pointerId === ev.pointerId && p.id === 'steer');
    if (!pad) return;
    // Relative drag from grab point — longer throw = less twitchy full lock.
    // ~18% of screen width (clamped) before max steer.
    const travel = Math.max(110, Math.min(168, window.innerWidth * 0.18));
    const raw = clamp((ev.clientX - pad.originX) / travel, -1, 1);
    this.steerX = steerCurve(raw);
  }

  private syncKnob() {
    if (!this.stickKnob || !this.stickBase) return;
    const max = this.stickBase.clientWidth * 0.34;
    this.stickKnob.style.transform = `translate(calc(-50% + ${this.steerSmooth * max}px), -50%)`;
    this.stickBase.classList.toggle('is-active', Math.abs(this.steerSmooth) > 0.05);
  }

  private syncPressedClass() {
    for (const [id, el] of this.pads) {
      if (id === 'steer') continue;
      el.classList.toggle('is-active', this.isHeld(id));
    }
  }
}

/** Combine keyboard + touch into one InputState (OR / max semantics). */
export function mergeInputStates(keyboard: InputState, touch: InputState): InputState {
  const out = createInputState();
  const steer = Math.abs(touch.steer) > Math.abs(keyboard.steer) ? touch.steer : keyboard.steer;
  out.steer = clamp(steer, -1, 1);
  out.throttle = Math.max(keyboard.throttle, touch.throttle);
  out.brake = Math.max(keyboard.brake, touch.brake);
  out.airbrakeL = keyboard.airbrakeL || touch.airbrakeL;
  out.airbrakeR = keyboard.airbrakeR || touch.airbrakeR;
  out.boost = keyboard.boost || touch.boost;
  out.startPressed = keyboard.startPressed || touch.startPressed;
  out.restartPressed = keyboard.restartPressed || touch.restartPressed;
  out.cameraTogglePressed = keyboard.cameraTogglePressed || touch.cameraTogglePressed;
  out.firePressed = keyboard.firePressed || touch.firePressed;
  out.nitroPressed = keyboard.nitroPressed || touch.nitroPressed;
  return out;
}
