/**
 * Session race settings — lap count + ship category (shared by the whole field).
 */

import { CONFIG } from '../core/config';

export type ShipClassId = 'beginner' | 'standard' | 'expert';
export type LapCount = 1 | 3 | 5;

export const LAP_OPTIONS = [1, 3, 5] as const satisfies readonly LapCount[];

export const SHIP_CLASS_OPTIONS: readonly {
  id: ShipClassId;
  title: string;
  blurb: string;
}[] = [
  { id: 'beginner', title: 'ROOKIE', blurb: 'Beginner — forgiving handling, lower top speed' },
  { id: 'standard', title: 'PILOT', blurb: 'Standard — balanced AG pack pace' },
  { id: 'expert', title: 'ACE', blurb: 'Expert — peak speed, sharper, less grip' },
];

export type ShipTune = {
  thrust: number;
  reverseThrust: number;
  boostForce: number;
  topSpeed: number;
  boostTopSpeed: number;
  dragLinear: number;
  dragQuadratic: number;
  throttleUpRate: number;
  throttleDownRate: number;
  turnRateLow: number;
  turnRateHigh: number;
  yawResponse: number;
  airbrakeYawGain: number;
  airControl: number;
  lateralGrip: number;
  airbrakeGrip: number;
  bankGain: number;
  slipLeanGain: number;
  pitchTrim: number;
  hoverHeight: number;
  hoverStiffness: number;
  hoverDamping: number;
  gravity: number;
  gradeAccel: number;
  gradePitch: number;
  trackBankFollow: number;
  bankCamber: number;
  airbrakeMinSpeed: number;
  boostChargeRate: number;
  boostDrainRate: number;
  boostMax: number;
  boostThrustMul: number;
  collisionRadius: number;
  collisionRestitution: number;
  collisionSpin: number;
  length: number;
  beam: number;
  mass: number;
};

type ClassMul = {
  topSpeed: number;
  thrust: number;
  turn: number;
  grip: number;
  boost: number;
  drag: number;
};

const CLASS_MUL: Record<ShipClassId, ClassMul> = {
  beginner: { topSpeed: 0.78, thrust: 0.88, turn: 1.22, grip: 1.18, boost: 0.85, drag: 1.05 },
  standard: { topSpeed: 1, thrust: 1, turn: 1, grip: 1, boost: 1, drag: 1 },
  expert: { topSpeed: 1.14, thrust: 1.08, turn: 0.88, grip: 0.86, boost: 1.12, drag: 0.94 },
};

function buildTune(cls: ShipClassId): ShipTune {
  const base = CONFIG.ship;
  const m = CLASS_MUL[cls];
  return {
    ...base,
    thrust: base.thrust * m.thrust,
    reverseThrust: base.reverseThrust * m.thrust,
    boostForce: base.boostForce * m.boost,
    topSpeed: base.topSpeed * m.topSpeed,
    boostTopSpeed: base.boostTopSpeed * m.topSpeed,
    dragLinear: base.dragLinear * m.drag,
    dragQuadratic: base.dragQuadratic * m.drag,
    turnRateLow: base.turnRateLow * m.turn,
    turnRateHigh: base.turnRateHigh * m.turn,
    lateralGrip: base.lateralGrip * m.grip,
    airbrakeGrip: base.airbrakeGrip * m.grip,
    boostThrustMul: base.boostThrustMul * (0.92 + 0.08 * m.boost),
  };
}

let activeClass: ShipClassId = 'standard';
let activeTune: ShipTune = buildTune('standard');

export function getShipClass(): ShipClassId {
  return activeClass;
}

/** Live ship tunables for physics (all racers share the session class). */
export function getShipTune(): ShipTune {
  return activeTune;
}

export function setShipClass(cls: ShipClassId) {
  activeClass = cls;
  activeTune = buildTune(cls);
}

export function raceLaps(ctx: { laps?: number } | null | undefined): number {
  const n = ctx?.laps;
  return typeof n === 'number' && n > 0 ? n : CONFIG.race.laps;
}
