/**
 * WaveSpace title / mode select — brand-first ink composition.
 * Mode cards + course picker (shipped tracks + procedural generate).
 */

import { clamp } from '../core/mathx';
import { HEX } from '../core/palette';
import { prefersTouchUi } from '../core/touchControls';
import { unlockAudioSync } from '../audio/unlock';
import {
  DEFAULT_LAYOUT,
  LAYOUTS,
  SHIPPED_LAYOUT_IDS,
  layoutFromUrl,
  makeSeedLayout,
  resolveLayout,
  type SeedBanks,
  type SeedGates,
  type SeedLength,
  type SeedRelief,
  type SeedShape,
  type SeedStyle,
  type SeedWidth,
  type TrackLayout,
} from '../race/layouts';
import {
  LAP_OPTIONS,
  SHIP_CLASS_OPTIONS,
  type LapCount,
  type ShipClassId,
} from '../race/raceSettings';
import { DISPLAY_STACK, FONT_STACK, PLATE_SKEW, inkText, plate, rgba, slantPath } from './inkDraw';
import { TrackPreview3D } from './trackPreview3d';

export type ModeSelectResult = 'race' | 'timeattack';

type Card = {
  id: ModeSelectResult;
  title: string;
  blurb: string;
  tag: string;
};

const MODES: Card[] = [
  {
    id: 'race',
    title: 'RACE',
    blurb: 'Full pack — rockets, lock-on, nitro.',
    tag: 'PACK',
  },
  {
    id: 'timeattack',
    title: 'TIMING',
    blurb: 'Solo hotlaps — no AI, no weapons.',
    tag: 'SOLO',
  },
];

type OptRowId = 'length' | 'style' | 'shape' | 'relief' | 'width' | 'banks' | 'gates';

type OptRow = {
  id: OptRowId;
  label: string;
  values: readonly string[];
  titles: readonly string[];
};

/** Two-column option grid (left / right). */
const OPT_LEFT: readonly OptRow[] = [
  {
    id: 'length',
    label: 'LENGTH',
    values: ['short', 'medium', 'long'],
    titles: ['SHORT', 'MID', 'LONG'],
  },
  {
    id: 'style',
    label: 'STYLE',
    values: ['flow', 'mixed', 'tech'],
    titles: ['FLOW', 'MIX', 'TECH'],
  },
  {
    id: 'shape',
    label: 'SHAPE',
    values: ['oval', 'organic', 'twisty'],
    titles: ['OVAL', 'WILD', 'TWIST'],
  },
  {
    id: 'relief',
    label: 'HILLS',
    values: ['flat', 'rolling', 'hilly'],
    titles: ['FLAT', 'ROLL', 'PEAK'],
  },
];

const OPT_RIGHT: readonly OptRow[] = [
  {
    id: 'width',
    label: 'WIDTH',
    values: ['tight', 'normal', 'wide'],
    titles: ['TIGHT', 'NORM', 'WIDE'],
  },
  {
    id: 'banks',
    label: 'TURNS',
    values: ['easy', 'mixed', 'hard'],
    titles: ['EASY', 'MIX', 'HARD'],
  },
  {
    id: 'gates',
    label: 'GATES',
    values: ['few', 'normal', 'many'],
    titles: ['FEW', 'MID', 'LOT'],
  },
];

const OPT_ROWS: readonly OptRow[] = [...OPT_LEFT, ...OPT_RIGHT];

type HitKind =
  | { kind: 'mode'; index: number }
  | { kind: 'shipped'; index: number }
  | { kind: 'generate' }
  | { kind: 'genOpt'; row: number; index: number }
  | { kind: 'laps'; index: number }
  | { kind: 'shipClass'; index: number };

export class ModeSelect {
  private selected = 0;
  private chosen: ModeSelectResult | null = null;
  private hover: HitKind | null = null;
  private t0 = performance.now();
  private readonly touch = prefersTouchUi();
  private readonly modes = MODES;
  /** Current course id (`canyon` / `seed-42`). */
  private trackId: string;
  private layout: TrackLayout;
  /** Flash when a new seed is generated. */
  private genFlash = 0;

  private genLength: SeedLength = 'medium';
  private genStyle: SeedStyle = 'mixed';
  private genShape: SeedShape = 'organic';
  private genRelief: SeedRelief = 'rolling';
  private genWidth: SeedWidth = 'normal';
  private genBanks: SeedBanks = 'mixed';
  private genGates: SeedGates = 'normal';
  private raceLaps: LapCount = 3;
  private shipClass: ShipClassId = 'standard';
  private readonly preview3d: TrackPreview3D;

  constructor(private canvas: HTMLCanvasElement) {
    const fromUrl = layoutFromUrl();
    this.layout = fromUrl;
    this.trackId = fromUrl.id;
    this.preview3d = new TrackPreview3D();
    this.preview3d.setLayout(this.layout, true);
    canvas.style.pointerEvents = 'auto';
    canvas.addEventListener('pointermove', this.onMove);
    canvas.addEventListener('pointerdown', this.onDown);
    window.addEventListener('keydown', this.onKey);
  }

  get result(): ModeSelectResult | null {
    return this.chosen;
  }

  get selectedTrackId(): string {
    return this.trackId;
  }

  /** Exact layout object so generated opts survive into the race. */
  get selectedLayout(): TrackLayout {
    return this.layout;
  }

  get selectedLaps(): LapCount {
    return this.raceLaps;
  }

  get selectedShipClass(): ShipClassId {
    return this.shipClass;
  }

  dispose(): void {
    this.preview3d.dispose();
    this.canvas.style.pointerEvents = 'none';
    this.canvas.removeEventListener('pointermove', this.onMove);
    this.canvas.removeEventListener('pointerdown', this.onDown);
    window.removeEventListener('keydown', this.onKey);
  }

  private setTrack(id: string) {
    this.trackId = id;
    this.layout = resolveLayout(id);
    this.preview3d.setLayout(this.layout, true);
  }

  private generateTrack() {
    const seed = (Math.random() * 0xffffffff) >>> 0;
    const layout = makeSeedLayout(seed, {
      length: this.genLength,
      style: this.genStyle,
      shape: this.genShape,
      relief: this.genRelief,
      width: this.genWidth,
      banks: this.genBanks,
      gates: this.genGates,
    });
    this.layout = layout;
    this.trackId = layout.id;
    this.genFlash = 1;
    this.preview3d.setLayout(this.layout, true);
  }

  private applyGenOpt(regen: boolean) {
    // Always rebuild so the map preview matches the selected options.
    if (regen) this.generateTrack();
  }

  private getOptValue(row: OptRowId): string {
    switch (row) {
      case 'length':
        return this.genLength;
      case 'style':
        return this.genStyle;
      case 'shape':
        return this.genShape;
      case 'relief':
        return this.genRelief;
      case 'width':
        return this.genWidth;
      case 'banks':
        return this.genBanks;
      case 'gates':
        return this.genGates;
    }
  }

  private setOptValue(row: OptRowId, value: string) {
    switch (row) {
      case 'length':
        this.genLength = value as SeedLength;
        break;
      case 'style':
        this.genStyle = value as SeedStyle;
        break;
      case 'shape':
        this.genShape = value as SeedShape;
        break;
      case 'relief':
        this.genRelief = value as SeedRelief;
        break;
      case 'width':
        this.genWidth = value as SeedWidth;
        break;
      case 'banks':
        this.genBanks = value as SeedBanks;
        break;
      case 'gates':
        this.genGates = value as SeedGates;
        break;
    }
  }

  private cycleOpt(rowIndex: number) {
    const row = OPT_ROWS[rowIndex];
    if (!row) return;
    const cur = this.getOptValue(row.id);
    const i = row.values.indexOf(cur);
    this.setOptValue(row.id, row.values[(i + 1) % row.values.length]!);
    this.applyGenOpt(true);
  }

  private genOptsBlurb(): string {
    const L = this.genLength === 'short' ? 'Short' : this.genLength === 'long' ? 'Long' : 'Mid';
    const S = this.genStyle === 'flow' ? 'Flow' : this.genStyle === 'tech' ? 'Tech' : 'Mix';
    const Sh = this.genShape === 'oval' ? 'Oval' : this.genShape === 'twisty' ? 'Twist' : 'Wild';
    const R = this.genRelief === 'flat' ? 'Flat' : this.genRelief === 'hilly' ? 'Peak' : 'Roll';
    return `${L} · ${S} · ${Sh} · ${R}`;
  }

  private cycleShipped(dir: number) {
    const ids = SHIPPED_LAYOUT_IDS;
    let i = ids.indexOf(this.trackId as (typeof ids)[number]);
    if (i < 0) i = 0;
    i = (i + dir + ids.length) % ids.length;
    this.setTrack(ids[i]!);
  }

  private layoutMetrics(cssW: number, cssH: number) {
    const s = clamp(cssH / 900, this.touch ? 0.78 : 0.72, 1.25);
    const brandH = this.touch ? cssH * 0.1 : cssH * 0.11;
    const footerH = (this.touch ? 26 : 30) * s;
    const setupH = (this.touch ? 52 : 56) * s;
    // Tall course panel so options + map never overlap / clip.
    const courseH = Math.min(
      this.touch ? 310 * s : 340 * s,
      cssH * (this.touch ? 0.46 : 0.44),
    );
    const gap = 8 * s;
    const modeAreaTop = brandH;
    const modeAreaBot = cssH - footerH - courseH - setupH - gap * 2;
    const modeCount = this.modes.length;
    const pw = Math.min(this.touch ? 640 * s : 720 * s, cssW - (this.touch ? 20 : 40) * s);
    const avail = Math.max(64 * s, modeAreaBot - modeAreaTop);
    const ph = Math.min(
      this.touch ? 58 * s : 64 * s,
      (avail - (modeCount - 1) * gap) / modeCount,
    );
    const stack = modeCount * ph + (modeCount - 1) * gap;
    const px = (cssW - pw) * 0.5;
    const py0 = modeAreaTop + Math.max(0, (avail - stack) * 0.3);
    const courseY = cssH - footerH - courseH;
    return {
      s,
      pw,
      ph,
      px,
      py0,
      gap,
      courseX: px,
      courseY,
      courseW: pw,
      courseH,
      footerH,
      setupX: px,
      setupY: courseY - gap - setupH,
      setupW: pw,
      setupH,
    };
  }

  private modeRect(m: ReturnType<ModeSelect['layoutMetrics']>, index: number) {
    return {
      px: m.px,
      py: m.py0 + index * (m.ph + m.gap),
      pw: m.pw,
      ph: m.ph,
    };
  }

  private courseParts(m: ReturnType<ModeSelect['layoutMetrics']>) {
    const { courseX, courseY, courseW, courseH, s } = m;
    const pad = 14 * s;
    const chipH = 34 * s;
    const optH = 26 * s;
    const rowGap = 6 * s;
    const colGap = 12 * s;
    const genW = Math.min(132 * s, courseW * 0.24);
    const chipGap = 8 * s;
    const chipsY = courseY + courseH - pad - chipH;
    const chipAvail = courseW - pad * 2 - genW - chipGap;
    const chipW = (chipAvail - chipGap * (SHIPPED_LAYOUT_IDS.length - 1)) / SHIPPED_LAYOUT_IDS.length;
    const chips = SHIPPED_LAYOUT_IDS.map((id, i) => ({
      id,
      x: courseX + pad + i * (chipW + chipGap),
      y: chipsY,
      w: chipW,
      h: chipH,
    }));
    const gen = {
      x: courseX + courseW - pad - genW,
      y: chipsY,
      w: genW,
      h: chipH,
    };

    // Left: map preview. Right: title + two-column options.
    const mapGap = 14 * s;
    const previewW = Math.min(courseW * 0.32, 220 * s);
    const previewH = Math.max(120 * s, chipsY - (courseY + pad) - 8 * s);
    const preview = {
      x: courseX + pad,
      y: courseY + pad,
      w: previewW,
      h: previewH,
    };

    const optsX = preview.x + preview.w + mapGap;
    const optsW = courseX + courseW - pad - optsX;
    const titleH = 52 * s;
    const rowsTop = courseY + pad + titleH;
    const rowsBot = chipsY - 10 * s;
    const leftCount = OPT_LEFT.length;
    const maxRows = Math.max(leftCount, OPT_RIGHT.length);
    const rowPitch = maxRows > 1 ? (rowsBot - rowsTop) / maxRows : optH;
    const useOptH = Math.min(optH, Math.max(22 * s, rowPitch - rowGap));

    const labelW = 52 * s;
    const optGap = 4 * s;
    const halfGap = colGap;
    const colW = (optsW - halfGap) * 0.5;

    const packCol = (rows: readonly OptRow[], colX: number, rowOffset: number) =>
      rows.map((row, ri) => {
        const y = rowsTop + ri * rowPitch;
        const n = row.values.length;
        const optX0 = colX + labelW;
        const optAvail = Math.max(40 * s, colW - labelW);
        const unit = (optAvail - optGap * (n - 1)) / n;
        let x = optX0;
        const optChips = Array.from({ length: n }, () => {
          const item = { x, y, w: Math.max(28 * s, unit), h: useOptH };
          x += unit + optGap;
          return item;
        });
        return { row, chips: optChips, labelX: colX, globalIndex: rowOffset + ri };
      });

    const leftCol = packCol(OPT_LEFT, optsX, 0);
    const rightCol = packCol(OPT_RIGHT, optsX + colW + halfGap, OPT_LEFT.length);
    const optRows = [...leftCol, ...rightCol];

    return { chips, gen, preview, pad, optRows, titleH, optsX, optsW };
  }

  private setupParts(m: ReturnType<ModeSelect['layoutMetrics']>) {
    const { setupX, setupY, setupW, setupH, s } = m;
    const pad = 12 * s;
    const rowH = Math.min(32 * s, setupH - pad * 2);
    const y = setupY + (setupH - rowH) * 0.5;
    const gap = 10 * s;
    const half = (setupW - pad * 2 - gap) * 0.5;

    const pack = (
      label: string,
      count: number,
      x0: number,
      w: number,
    ) => {
      const labelW = 52 * s;
      const chipGap = 5 * s;
      const avail = w - labelW;
      const chipW = (avail - chipGap * (count - 1)) / count;
      const chips = Array.from({ length: count }, (_, i) => ({
        x: x0 + labelW + i * (chipW + chipGap),
        y,
        w: chipW,
        h: rowH,
      }));
      return { label, labelX: x0, chips };
    };

    return {
      pad,
      y,
      rowH,
      laps: pack('LAPS', LAP_OPTIONS.length, setupX + pad, half),
      ship: pack('SHIP', SHIP_CLASS_OPTIONS.length, setupX + pad + half + gap, half),
    };
  }

  private hitAt(clientX: number, clientY: number): HitKind | null {
    const rect = this.canvas.getBoundingClientRect();
    const x = clientX - rect.left;
    const y = clientY - rect.top;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const cssW = this.canvas.width / dpr;
    const cssH = this.canvas.height / dpr;
    const m = this.layoutMetrics(cssW, cssH);
    const parts = this.courseParts(m);
    const setup = this.setupParts(m);
    for (let i = 0; i < parts.chips.length; i++) {
      const c = parts.chips[i]!;
      if (x >= c.x && x <= c.x + c.w && y >= c.y && y <= c.y + c.h) {
        return { kind: 'shipped', index: i };
      }
    }
    const g = parts.gen;
    if (x >= g.x && x <= g.x + g.w && y >= g.y && y <= g.y + g.h) {
      return { kind: 'generate' };
    }
    for (let ri = 0; ri < parts.optRows.length; ri++) {
      const chips = parts.optRows[ri]!.chips;
      for (let i = 0; i < chips.length; i++) {
        const c = chips[i]!;
        if (x >= c.x && x <= c.x + c.w && y >= c.y && y <= c.y + c.h) {
          return { kind: 'genOpt', row: parts.optRows[ri]!.globalIndex, index: i };
        }
      }
    }
    for (let i = 0; i < setup.laps.chips.length; i++) {
      const c = setup.laps.chips[i]!;
      if (x >= c.x && x <= c.x + c.w && y >= c.y && y <= c.y + c.h) {
        return { kind: 'laps', index: i };
      }
    }
    for (let i = 0; i < setup.ship.chips.length; i++) {
      const c = setup.ship.chips[i]!;
      if (x >= c.x && x <= c.x + c.w && y >= c.y && y <= c.y + c.h) {
        return { kind: 'shipClass', index: i };
      }
    }
    for (let i = 0; i < this.modes.length; i++) {
      const r = this.modeRect(m, i);
      if (x >= r.px && x <= r.px + r.pw && y >= r.py && y <= r.py + r.ph) {
        return { kind: 'mode', index: i };
      }
    }
    return null;
  }

  private onMove = (ev: PointerEvent): void => {
    const hit = this.hitAt(ev.clientX, ev.clientY);
    this.hover = hit;
    if (hit?.kind === 'mode') this.selected = hit.index;
  };

  private trySelectMode(index: number): void {
    const mode = this.modes[index];
    if (!mode) return;
    this.chosen = mode.id;
  }

  private onDown = (ev: PointerEvent): void => {
    unlockAudioSync();
    const hit = this.hitAt(ev.clientX, ev.clientY);
    this.hover = hit;
    if (!hit) return;
    if (hit.kind === 'mode') {
      this.selected = hit.index;
      this.trySelectMode(hit.index);
      return;
    }
    if (hit.kind === 'shipped') {
      const id = SHIPPED_LAYOUT_IDS[hit.index];
      if (id) this.setTrack(id);
      return;
    }
    if (hit.kind === 'generate') {
      this.generateTrack();
      return;
    }
    if (hit.kind === 'genOpt') {
      const row = OPT_ROWS[hit.row];
      const value = row?.values[hit.index];
      if (row && value) {
        this.setOptValue(row.id, value);
        this.applyGenOpt(true);
      }
      return;
    }
    if (hit.kind === 'laps') {
      const n = LAP_OPTIONS[hit.index];
      if (n) this.raceLaps = n;
      return;
    }
    if (hit.kind === 'shipClass') {
      const cls = SHIP_CLASS_OPTIONS[hit.index]?.id;
      if (cls) this.shipClass = cls;
    }
  };

  private onKey = (ev: KeyboardEvent): void => {
    const n = this.modes.length;
    if (ev.code === 'ArrowDown' || ev.code === 'KeyS') this.selected = (this.selected + 1) % n;
    if (ev.code === 'ArrowUp' || ev.code === 'KeyW') this.selected = (this.selected - 1 + n) % n;
    if (ev.code === 'ArrowLeft' || ev.code === 'KeyA') {
      ev.preventDefault();
      this.cycleShipped(-1);
    }
    if (ev.code === 'ArrowRight' || ev.code === 'KeyD') {
      ev.preventDefault();
      this.cycleShipped(1);
    }
    if (ev.code === 'KeyG') {
      ev.preventDefault();
      this.generateTrack();
    }
    // 1–7 cycle generator rows; L cycles laps; C cycles ship class
    const digit = /^Digit([1-7])$/.exec(ev.code);
    if (digit) {
      ev.preventDefault();
      this.cycleOpt(Number(digit[1]) - 1);
    }
    if (ev.code === 'KeyL') {
      ev.preventDefault();
      const i = LAP_OPTIONS.indexOf(this.raceLaps);
      this.raceLaps = LAP_OPTIONS[(i + 1) % LAP_OPTIONS.length]!;
    }
    if (ev.code === 'KeyC') {
      ev.preventDefault();
      const i = SHIP_CLASS_OPTIONS.findIndex((c) => c.id === this.shipClass);
      this.shipClass = SHIP_CLASS_OPTIONS[(i + 1) % SHIP_CLASS_OPTIONS.length]!.id;
    }
    if (ev.code === 'Enter' || ev.code === 'Space') {
      ev.preventDefault();
      this.trySelectMode(this.selected);
    }
  };

  private drawPreview(
    g: CanvasRenderingContext2D,
    layout: TrackLayout,
    x: number,
    y: number,
    w: number,
    h: number,
    s: number,
    accent: number,
  ) {
    const verts = layout.verts;
    if (verts.length < 3 || w < 8 || h < 8) return;

    // Map plate
    g.save();
    g.beginPath();
    const r = 8 * s;
    g.moveTo(x + r, y);
    g.arcTo(x + w, y, x + w, y + h, r);
    g.arcTo(x + w, y + h, x, y + h, r);
    g.arcTo(x, y + h, x, y, r);
    g.arcTo(x, y, x + w, y, r);
    g.closePath();
    g.fillStyle = rgba(HEX.hudInk, 0.92);
    g.fill();
    g.strokeStyle = rgba(accent, 0.45);
    g.lineWidth = Math.max(1.5, 1.8 * s);
    g.stroke();
    g.clip();

    // Soft grid
    g.strokeStyle = rgba(HEX.hudDim, 0.18);
    g.lineWidth = 1;
    const step = 18 * s;
    for (let gx = x + step; gx < x + w; gx += step) {
      g.beginPath();
      g.moveTo(gx, y);
      g.lineTo(gx, y + h);
      g.stroke();
    }
    for (let gy = y + step; gy < y + h; gy += step) {
      g.beginPath();
      g.moveTo(x, gy);
      g.lineTo(x + w, gy);
      g.stroke();
    }

    let minX = Infinity;
    let maxX = -Infinity;
    let minZ = Infinity;
    let maxZ = -Infinity;
    for (const [vx, vz] of verts) {
      if (vx < minX) minX = vx;
      if (vx > maxX) maxX = vx;
      if (vz < minZ) minZ = vz;
      if (vz > maxZ) maxZ = vz;
    }
    const spanX = Math.max(1, maxX - minX);
    const spanZ = Math.max(1, maxZ - minZ);
    const pad = 16 * s;
    const scale = Math.min((w - pad * 2) / spanX, (h - pad * 2) / spanZ);
    const cx = x + w * 0.5;
    const cy = y + h * 0.5;
    const midX = (minX + maxX) * 0.5;
    const midZ = (minZ + maxZ) * 0.5;
    const toPx = (vx: number, vz: number) => ({
      px: cx + (vx - midX) * scale,
      py: cy - (vz - midZ) * scale,
    });

    // Dense polyline (lerp edges) so the ribbon reads as a circuit, not a polygon.
    const pts: { px: number; py: number }[] = [];
    const segs = Math.max(3, Math.round(10 * s));
    for (let i = 0; i < verts.length; i++) {
      const a = verts[i]!;
      const b = verts[(i + 1) % verts.length]!;
      for (let k = 0; k < segs; k++) {
        const t = k / segs;
        pts.push(toPx(a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t));
      }
    }
    pts.push(pts[0]!);

    const ribbon = Math.max(5, Math.min(14, 9 * s * (scale / 0.35)));

    const strokePath = () => {
      g.beginPath();
      for (let i = 0; i < pts.length; i++) {
        const p = pts[i]!;
        if (i === 0) g.moveTo(p.px, p.py);
        else g.lineTo(p.px, p.py);
      }
    };

    // Outer ink
    strokePath();
    g.strokeStyle = rgba(HEX.ink, 0.85);
    g.lineWidth = ribbon + 3.5 * s;
    g.lineJoin = 'round';
    g.lineCap = 'round';
    g.stroke();

    // Track body
    strokePath();
    g.strokeStyle = rgba(accent, 0.55);
    g.lineWidth = ribbon;
    g.stroke();

    // Center racing line
    strokePath();
    g.strokeStyle = rgba(HEX.hudPaper, 0.95);
    g.lineWidth = Math.max(1.2, 1.6 * s);
    g.setLineDash([5 * s, 4 * s]);
    g.stroke();
    g.setLineDash([]);

    // Start / finish
    const p0 = toPx(verts[0]![0], verts[0]![1]);
    const p1 = toPx(verts[1]![0], verts[1]![1]);
    let dx = p1.px - p0.px;
    let dy = p1.py - p0.py;
    const len = Math.hypot(dx, dy) || 1;
    dx /= len;
    dy /= len;
    const nx = -dy;
    const ny = dx;
    const half = ribbon * 0.65;
    g.strokeStyle = rgba(HEX.boostHot, 1);
    g.lineWidth = Math.max(2, 2.4 * s);
    g.beginPath();
    g.moveTo(p0.px - nx * half, p0.py - ny * half);
    g.lineTo(p0.px + nx * half, p0.py + ny * half);
    g.stroke();

    // Direction chevron
    const tip = 7 * s;
    g.fillStyle = rgba(HEX.boostHot, 1);
    g.beginPath();
    g.moveTo(p0.px + dx * tip * 1.6, p0.py + dy * tip * 1.6);
    g.lineTo(p0.px - dx * tip * 0.4 - nx * tip * 0.7, p0.py - dy * tip * 0.4 - ny * tip * 0.7);
    g.lineTo(p0.px - dx * tip * 0.4 + nx * tip * 0.7, p0.py - dy * tip * 0.4 + ny * tip * 0.7);
    g.closePath();
    g.fill();

    g.restore();
  }

  draw(): void {
    const g = this.canvas.getContext('2d');
    if (!g) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const cssW = window.innerWidth;
    const cssH = window.innerHeight;
    if (this.canvas.width !== Math.floor(cssW * dpr) || this.canvas.height !== Math.floor(cssH * dpr)) {
      this.canvas.width = Math.floor(cssW * dpr);
      this.canvas.height = Math.floor(cssH * dpr);
      this.canvas.style.width = `${cssW}px`;
      this.canvas.style.height = `${cssH}px`;
    }

    const t = (performance.now() - this.t0) / 1000;
    if (this.genFlash > 0) this.genFlash = Math.max(0, this.genFlash - 0.04);

    g.clearRect(0, 0, this.canvas.width, this.canvas.height);
    g.save();
    g.scale(dpr, dpr);

    const sky = g.createLinearGradient(0, 0, 0, cssH);
    sky.addColorStop(0, rgba(HEX.skyZenith, 1));
    sky.addColorStop(0.4, rgba(HEX.voidMid, 1));
    sky.addColorStop(0.75, rgba(HEX.voidDeep, 1));
    sky.addColorStop(1, rgba(HEX.hudInk, 1));
    g.fillStyle = sky;
    g.fillRect(0, 0, cssW, cssH);

    g.save();
    g.globalAlpha = 0.12;
    for (let i = 0; i < 8; i++) {
      const y = cssH * 0.5 + i * 22 + Math.sin(t * 1.4 + i) * 8;
      g.strokeStyle = rgba(HEX.boost, 1);
      g.lineWidth = 2;
      g.beginPath();
      g.moveTo(0, y);
      g.lineTo(cssW, y - 40);
      g.stroke();
    }
    g.restore();

    const vig = g.createRadialGradient(cssW * 0.5, cssH * 0.3, cssH * 0.1, cssW * 0.5, cssH * 0.5, cssH * 0.85);
    vig.addColorStop(0, rgba(HEX.hudInk, 0));
    vig.addColorStop(1, rgba(HEX.hudInk, 0.55));
    g.fillStyle = vig;
    g.fillRect(0, 0, cssW, cssH);

    const m = this.layoutMetrics(cssW, cssH);
    const { s } = m;
    const brandY = cssH * (this.touch ? 0.04 : 0.048);

    inkText(g, 'WAVESPACE', cssW * 0.5, brandY, {
      font: `900 ${Math.round((this.touch ? 28 : 38) * s)}px ${DISPLAY_STACK}`,
      fill: rgba(HEX.foam, 1),
      align: 'center',
      baseline: 'middle',
      tracking: 5 * s,
      ink: rgba(HEX.ink, 1),
      inkWidth: 3.5 * s,
      ghost: rgba(HEX.boost, 0.5),
      ghostDx: 2 * s,
      ghostDy: 3 * s,
    });
    inkText(g, 'ANTI-GRAV RACING', cssW * 0.5, brandY + (this.touch ? 20 : 26) * s, {
      font: `700 ${Math.round(10 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.waterCrest, 1),
      align: 'center',
      baseline: 'middle',
      tracking: 3 * s,
    });

    this.modes.forEach((mode, i) => {
      const { px, py, pw, ph } = this.modeRect(m, i);
      const active = i === this.selected;
      const accent = mode.id === 'race' ? HEX.warn : HEX.hull3;
      const hoverMode = this.hover?.kind === 'mode' && this.hover.index === i;

      plate(g, slantPath(px, py, pw, ph, ph * PLATE_SKEW * 0.55), s, {
        edge: rgba(active || hoverMode ? accent : HEX.hudDim, active ? 1 : hoverMode ? 0.85 : 0.45),
        hatchRect: [px, py, pw, ph],
      });

      if (active) {
        g.fillStyle = rgba(accent, 0.95);
        g.fillRect(px + 3 * s, py + 8 * s, 4 * s, ph - 16 * s);
      }

      const textX = px + 20 * s;
      inkText(g, mode.tag, textX, py + ph * 0.32, {
        font: `800 ${Math.round(9 * s)}px ${FONT_STACK}`,
        fill: rgba(accent, 1),
        tracking: 2 * s,
        baseline: 'middle',
      });
      inkText(g, mode.title, textX, py + ph * 0.62, {
        font: `900 ${Math.round(Math.min(22 * s, ph * 0.42))}px ${DISPLAY_STACK}`,
        fill: rgba(HEX.hudPaper, 1),
        tracking: 2 * s,
        baseline: 'middle',
      });

      if (active) {
        inkText(g, this.touch ? 'TAP' : 'ENTER', px + pw - 18 * s, py + ph * 0.55, {
          font: `800 ${Math.round(11 * s)}px ${FONT_STACK}`,
          fill: rgba(HEX.boostHot, 1),
          align: 'right',
          tracking: 2 * s,
          baseline: 'middle',
        });
      }
    });

    // ── Race setup: laps + ship class ────────────────────────────────────────
    const setup = this.setupParts(m);
    plate(
      g,
      slantPath(m.setupX, m.setupY, m.setupW, m.setupH, m.setupH * PLATE_SKEW * 0.2),
      s,
      {
        edge: rgba(HEX.hudDim, 0.5),
        hatchRect: [m.setupX, m.setupY, m.setupW, m.setupH],
      },
    );

    const drawSetupGroup = (
      group: ReturnType<ModeSelect['setupParts']>['laps'],
      titles: readonly string[],
      selectedIndex: number,
      kind: 'laps' | 'shipClass',
      accent: number,
    ) => {
      inkText(g, group.label, group.labelX, setup.y + setup.rowH * 0.5, {
        font: `800 ${Math.round(9 * s)}px ${FONT_STACK}`,
        fill: rgba(HEX.hudDim, 0.95),
        tracking: 1.2 * s,
        baseline: 'middle',
      });
      group.chips.forEach((chip, i) => {
        const on = i === selectedIndex;
        const hot = this.hover?.kind === kind && this.hover.index === i;
        g.fillStyle = on ? rgba(accent, 0.28) : rgba(HEX.hudInk, 0.55);
        g.strokeStyle = rgba(on || hot ? accent : HEX.hudDim, on ? 1 : hot ? 0.85 : 0.45);
        g.lineWidth = Math.max(1.2, 1.4 * s);
        g.beginPath();
        g.roundRect(chip.x, chip.y, chip.w, chip.h, 4 * s);
        g.fill();
        g.stroke();
        inkText(g, titles[i]!, chip.x + chip.w * 0.5, chip.y + chip.h * 0.5, {
          font: `800 ${Math.round(10 * s)}px ${FONT_STACK}`,
          fill: rgba(on ? HEX.hudPaper : HEX.hudDim, 1),
          align: 'center',
          baseline: 'middle',
        });
      });
    };

    drawSetupGroup(
      setup.laps,
      LAP_OPTIONS.map((n) => String(n)),
      LAP_OPTIONS.indexOf(this.raceLaps),
      'laps',
      HEX.waterCrest,
    );
    drawSetupGroup(
      setup.ship,
      SHIP_CLASS_OPTIONS.map((c) => c.title),
      SHIP_CLASS_OPTIONS.findIndex((c) => c.id === this.shipClass),
      'shipClass',
      HEX.boostHot,
    );

    // ── Course picker ────────────────────────────────────────────────────────
    const parts = this.courseParts(m);
    const courseAccent = this.trackId.startsWith('seed-') ? HEX.boostHot : HEX.waterCrest;
    plate(
      g,
      slantPath(m.courseX, m.courseY, m.courseW, m.courseH, m.courseH * PLATE_SKEW * 0.12),
      s,
      {
        edge: rgba(courseAccent, 0.55 + this.genFlash * 0.4),
        hatchRect: [m.courseX, m.courseY, m.courseW, m.courseH],
      },
    );

    this.preview3d.setLayout(this.layout);
    const accentCss =
      courseAccent === HEX.boostHot ? 'rgba(255,138,74,0.85)' : 'rgba(30,240,240,0.75)';
    this.preview3d.setAccent(accentCss);
    const live3d = this.preview3d.render(parts.preview);
    // Preview canvas sits above the HUD — always keep a 2D outline underneath
    // so a slow rebuild never leaves an empty plate.
    if (!live3d) {
      this.drawPreview(
        g,
        this.layout,
        parts.preview.x,
        parts.preview.y,
        parts.preview.w,
        parts.preview.h,
        s,
        courseAccent,
      );
    }

    const titleX = parts.optsX;
    inkText(g, 'COURSE', titleX, m.courseY + parts.pad + 8 * s, {
      font: `800 ${Math.round(9 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.hudDim, 1),
      tracking: 2.5 * s,
      baseline: 'middle',
    });

    const layoutName = (this.layout.name || DEFAULT_LAYOUT.name).toUpperCase();
    inkText(g, layoutName, titleX, m.courseY + parts.pad + 26 * s, {
      font: `800 ${Math.round(16 * s)}px ${DISPLAY_STACK}`,
      fill: rgba(HEX.hudPaper, 1),
      tracking: 1.2 * s,
      baseline: 'middle',
    });

    const shipped = LAYOUTS[this.trackId];
    const blurb = shipped
      ? this.trackId === 'canyon'
        ? 'Hairpin · chicane · commit straights'
        : this.trackId === 'oval'
          ? 'Wide stadium · few hard brakes'
          : 'Tight radii · short straights'
      : this.genOptsBlurb();
    inkText(g, blurb, titleX, m.courseY + parts.pad + 44 * s, {
      font: `700 ${Math.round(11 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.hudDim, 0.95),
      baseline: 'middle',
    });

    // Option chips — axis-aligned for readable labels.
    parts.optRows.forEach((block) => {
      const row = block.row;
      const midY = block.chips[0]!.y + block.chips[0]!.h * 0.5;
      inkText(g, row.label, block.labelX, midY, {
        font: `800 ${Math.round(9 * s)}px ${FONT_STACK}`,
        fill: rgba(HEX.hudDim, 0.95),
        tracking: 1 * s,
        baseline: 'middle',
      });
      block.chips.forEach((chip, i) => {
        const on = this.getOptValue(row.id) === row.values[i];
        const hot =
          this.hover?.kind === 'genOpt' &&
          this.hover.row === block.globalIndex &&
          this.hover.index === i;
        // Flat chips — slant ate label edges on narrow cells.
        g.fillStyle = on ? rgba(HEX.boost, 0.32) : rgba(HEX.hudInk, 0.55);
        g.strokeStyle = rgba(on || hot ? HEX.boostHot : HEX.hudDim, on ? 1 : hot ? 0.85 : 0.45);
        g.lineWidth = Math.max(1.2, 1.4 * s);
        const rr = 4 * s;
        g.beginPath();
        g.roundRect(chip.x, chip.y, chip.w, chip.h, rr);
        g.fill();
        g.stroke();
        inkText(g, row.titles[i]!, chip.x + chip.w * 0.5, chip.y + chip.h * 0.5, {
          font: `800 ${Math.round(10 * s)}px ${FONT_STACK}`,
          fill: rgba(on ? HEX.hudPaper : HEX.hudDim, 1),
          align: 'center',
          baseline: 'middle',
        });
      });
    });

    parts.chips.forEach((chip, i) => {
      const id = SHIPPED_LAYOUT_IDS[i]!;
      const on = this.trackId === id;
      const hot = this.hover?.kind === 'shipped' && this.hover.index === i;
      const label = LAYOUTS[id]?.name.toUpperCase() ?? id.toUpperCase();
      g.fillStyle = on ? rgba(HEX.waterCrest, 0.22) : rgba(HEX.hudInk, 0.5);
      g.strokeStyle = rgba(on || hot ? HEX.waterCrest : HEX.hudDim, on ? 1 : hot ? 0.85 : 0.45);
      g.lineWidth = Math.max(1.2, 1.4 * s);
      g.beginPath();
      g.roundRect(chip.x, chip.y, chip.w, chip.h, 5 * s);
      g.fill();
      g.stroke();
      inkText(g, label, chip.x + chip.w * 0.5, chip.y + chip.h * 0.5, {
        font: `800 ${Math.round(12 * s)}px ${FONT_STACK}`,
        fill: rgba(on ? HEX.hudPaper : HEX.hudDim, 1),
        align: 'center',
        baseline: 'middle',
      });
    });

    {
      const gen = parts.gen;
      const hot = this.hover?.kind === 'generate' || this.genFlash > 0.2;
      g.fillStyle = rgba(hot ? HEX.boost : HEX.hudInk, 1);
      g.strokeStyle = rgba(HEX.boostHot, hot ? 1 : 0.75);
      g.lineWidth = Math.max(1.5, 1.8 * s);
      g.beginPath();
      g.roundRect(gen.x, gen.y, gen.w, gen.h, 5 * s);
      g.fill();
      g.stroke();
      inkText(g, this.touch ? 'BUILD' : 'BUILD · G', gen.x + gen.w * 0.5, gen.y + gen.h * 0.5, {
        font: `800 ${Math.round(12 * s)}px ${FONT_STACK}`,
        fill: rgba(HEX.hudPaper, 1),
        align: 'center',
        baseline: 'middle',
      });
    }

    inkText(
      g,
      this.touch
        ? 'LAPS · SHIP · COURSE · TAP RACE OR TIMING'
        : 'W/S MODE  ·  L LAPS  ·  C SHIP  ·  A/D COURSE  ·  G BUILD  ·  ENTER',
      cssW * 0.5,
      cssH - (this.touch ? 12 : 16) * s,
      {
        font: `700 ${Math.round(9 * s)}px ${FONT_STACK}`,
        fill: rgba(HEX.hudDim, 0.75),
        align: 'center',
        tracking: 1.2 * s,
        baseline: 'middle',
      },
    );

    g.restore();
  }
}
