/**
 * AAA cel race floor — relief deck, banked shoulders, canyon rails, void apron.
 * Built from the elevated centreline. Kerbs are cosmetic; physics stays open-course.
 */

import {
  BufferAttribute,
  BufferGeometry,
  DoubleSide,
  Group,
  Mesh,
  Vector3,
} from 'three';
import { PAL } from '../core/palette';
import { applyCel, createCelMaterial, type CelMaterialSet } from '../render/celMaterial';
import type { Track } from '../race/track';

import { CONFIG } from '../core/config';

const DECK_HALF = CONFIG.race.deckHalf;
const APRON_HALF = 300;
const SEG = 360;
const CANYON_DROP = 10;

/**
 * Riding surfaces keep geometric relief for silhouette, but light as flat-up
 * plates so grade/bank never shove a stretch into the darkest cel band.
 */
function flattenUpNormals(geo: BufferGeometry) {
  const nor = geo.getAttribute('normal');
  if (!nor) return;
  for (let i = 0; i < nor.count; i++) nor.setXYZ(i, 0, 1, 0);
  nor.needsUpdate = true;
}

/** Soft upward bias for walls/rails that still need some facing variation. */
function liftNormals(geo: BufferGeometry, upBias = 0.55) {
  const nor = geo.getAttribute('normal');
  if (!nor) return;
  for (let i = 0; i < nor.count; i++) {
    let nx = nor.getX(i);
    let ny = nor.getY(i) + upBias;
    let nz = nor.getZ(i);
    const len = Math.hypot(nx, ny, nz) || 1;
    nor.setXYZ(i, nx / len, ny / len, nz / len);
  }
  nor.needsUpdate = true;
}

function bothSides(set: CelMaterialSet) {
  set.main.side = DoubleSide;
  set.prepass.side = DoubleSide;
  if (set.outline) set.outline.side = DoubleSide;
}

const _tp = {
  position: new Vector3(),
  tangent: new Vector3(0, 0, 1),
  curvature: 0,
  u: 0,
};
const _nFloor = new Vector3(0, 1, 0);

/** World point on the banked deck at (u, lateral) with optional y offset. */
function deckXZ(
  track: Track,
  u: number,
  lateral: number,
  yOff: number,
): { x: number; y: number; z: number; nx: number; ny: number; nz: number } {
  track.sample(u, _tp);
  // Vertical loops: ride the surface frame (tangent × normal = track-right).
  if (track.hasVerticalLoops) {
    const n = track.surfaceNormalAt(u, _nFloor);
    let rx = _tp.tangent.y * n.z - _tp.tangent.z * n.y;
    let ry = _tp.tangent.z * n.x - _tp.tangent.x * n.z;
    let rz = _tp.tangent.x * n.y - _tp.tangent.y * n.x;
    const rl = Math.hypot(rx, ry, rz) || 1;
    rx /= rl;
    ry /= rl;
    rz /= rl;
    return {
      x: _tp.position.x + rx * lateral,
      y: _tp.position.y + ry * lateral + yOff * n.y,
      z: _tp.position.z + rz * lateral,
      nx: n.x,
      ny: n.y,
      nz: n.z,
    };
  }
  const bank = track.bankAt(u);
  const rx = -_tp.tangent.z;
  const rz = _tp.tangent.x;
  const cosB = Math.cos(bank);
  const sinB = Math.sin(bank);
  // Bank rotates about the centreline: outer rail lifts on left turns.
  const x = _tp.position.x + rx * lateral * cosB;
  const z = _tp.position.z + rz * lateral * cosB;
  const y = _tp.position.y + lateral * sinB + yOff;
  // Surface normal tilted by bank (approx; good enough for cel lighting).
  const nx = -rx * sinB;
  const ny = cosB;
  const nz = -rz * sinB;
  return { x, y, z, nx, ny, nz };
}

function pushN(nor: number[], n: { nx: number; ny: number; nz: number }, count: number) {
  for (let i = 0; i < count; i++) nor.push(n.nx, n.ny, n.nz);
}

/** Full-width strip following relief. */
function buildFullStrip(
  track: Track,
  halfW: number,
  yOff: number,
  segs: number,
  flattenOuter = false,
  keepNormals = false,
): BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  const idx: number[] = [];

  for (let i = 0; i <= segs; i++) {
    const u = i / segs;
    const L = deckXZ(track, u, -halfW, yOff);
    const R = deckXZ(track, u, halfW, yOff);
    if (flattenOuter) {
      // Apron sinks toward the void mean so hills punch through.
      L.y = Math.min(L.y, yOff - 0.4);
      R.y = Math.min(R.y, yOff - 0.4);
      L.nx = 0; L.ny = 1; L.nz = 0;
      R.nx = 0; R.ny = 1; R.nz = 0;
    }
    pos.push(L.x, L.y, L.z, R.x, R.y, R.z);
    nor.push(L.nx, L.ny, L.nz, R.nx, R.ny, R.nz);
    if (i < segs) {
      const a = i * 2;
      idx.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
    }
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  geo.setAttribute('normal', new BufferAttribute(new Float32Array(nor), 3));
  geo.setIndex(idx);
  if (!flattenOuter && !keepNormals) flattenUpNormals(geo);
  geo.computeBoundingSphere();
  return geo;
}

/** Two shoulder strips at ±[inner, outer]. */
function buildShoulders(
  track: Track,
  inner: number,
  outer: number,
  yOff: number,
  segs: number,
  keepNormals = false,
): BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  const idx: number[] = [];
  let vert = 0;

  for (const side of [-1, 1] as const) {
    for (let i = 0; i < segs; i++) {
      const u0 = i / segs;
      const u1 = (i + 1) / segs;
      const a = deckXZ(track, u0, side * inner, yOff);
      const b = deckXZ(track, u0, side * outer, yOff);
      const c = deckXZ(track, u1, side * outer, yOff);
      const d = deckXZ(track, u1, side * inner, yOff);
      const v = vert;
      pos.push(a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z, d.x, d.y, d.z);
      pushN(nor, a, 4);
      idx.push(v, v + 1, v + 2, v, v + 2, v + 3);
      vert += 4;
    }
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  geo.setAttribute('normal', new BufferAttribute(new Float32Array(nor), 3));
  geo.setIndex(idx);
  if (!keepNormals) flattenUpNormals(geo);
  return geo;
}

function buildPanelDeck(track: Track, half: number, yOff: number, segs: number, keepNormals = false): BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  const idx: number[] = [];
  let vert = 0;
  const bands = [-half, -half * 0.42, half * 0.42, half];

  for (let i = 0; i < segs; i++) {
    const u0 = i / segs;
    const u1 = (i + 1) / segs;
    for (let b = 0; b < bands.length - 1; b++) {
      const a0 = bands[b];
      const a1 = bands[b + 1];
      const p0 = deckXZ(track, u0, a0, yOff);
      const p1 = deckXZ(track, u0, a1, yOff);
      const p2 = deckXZ(track, u1, a1, yOff);
      const p3 = deckXZ(track, u1, a0, yOff);
      const v = vert;
      pos.push(p0.x, p0.y, p0.z, p1.x, p1.y, p1.z, p2.x, p2.y, p2.z, p3.x, p3.y, p3.z);
      pushN(nor, p0, 4);
      idx.push(v, v + 1, v + 2, v, v + 2, v + 3);
      vert += 4;
    }
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  geo.setAttribute('normal', new BufferAttribute(new Float32Array(nor), 3));
  geo.setIndex(idx);
  if (!keepNormals) flattenUpNormals(geo);
  geo.computeBoundingSphere();
  return geo;
}

function buildEdgeRails(track: Track, half: number, yOff: number, segs: number): BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  const idx: number[] = [];
  const h = 1.15;
  const t = 0.7;
  let vert = 0;

  for (const side of [-1, 1] as const) {
    for (let i = 0; i < segs; i++) {
      const u0 = i / segs;
      const u1 = (i + 1) / segs;
      const a = deckXZ(track, u0, side * half, yOff);
      const b = deckXZ(track, u0, side * (half + t), yOff);
      const c = deckXZ(track, u1, side * (half + t), yOff);
      const d = deckXZ(track, u1, side * half, yOff);
      const v = vert;
      pos.push(
        a.x, a.y, a.z,
        b.x, b.y, b.z,
        c.x, c.y, c.z,
        d.x, d.y, d.z,
        a.x, a.y + h, a.z,
        b.x, b.y + h, b.z,
        c.x, c.y + h, c.z,
        d.x, d.y + h, d.z,
      );
      for (let k = 0; k < 8; k++) nor.push(a.nx, a.ny, a.nz);
      idx.push(v + 4, v + 5, v + 6, v + 4, v + 6, v + 7);
      idx.push(v + 1, v + 5, v + 6, v + 1, v + 6, v + 2);
      idx.push(v, v + 4, v + 7, v, v + 7, v + 3);
      vert += 8;
    }
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  geo.setAttribute('normal', new BufferAttribute(new Float32Array(nor), 3));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  liftNormals(geo, 1.1);
  geo.computeBoundingSphere();
  return geo;
}

/** Vertical canyon faces dropping from the deck lip into the void. */
function buildCanyonWalls(track: Track, half: number, segs: number): BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  const idx: number[] = [];
  let vert = 0;

  for (const side of [-1, 1] as const) {
    for (let i = 0; i < segs; i++) {
      const u0 = i / segs;
      const u1 = (i + 1) / segs;
      const top0 = deckXZ(track, u0, side * half, 0);
      const top1 = deckXZ(track, u1, side * half, 0);
      track.sample(u0, _tp);
      const rx0 = -_tp.tangent.z * side;
      const rz0 = _tp.tangent.x * side;
      track.sample(u1, _tp);
      const rx1 = -_tp.tangent.z * side;
      const rz1 = _tp.tangent.x * side;
      const b0x = top0.x + rx0 * 2.4;
      const b0z = top0.z + rz0 * 2.4;
      const b1x = top1.x + rx1 * 2.4;
      const b1z = top1.z + rz1 * 2.4;
      const v = vert;
      pos.push(
        top0.x, top0.y - 0.05, top0.z,
        b0x, top0.y - CANYON_DROP, b0z,
        b1x, top1.y - CANYON_DROP, b1z,
        top1.x, top1.y - 0.05, top1.z,
      );
      nor.push(rx0, 0.15, rz0, rx0, 0.15, rz0, rx1, 0.15, rz1, rx1, 0.15, rz1);
      idx.push(v, v + 1, v + 2, v, v + 2, v + 3);
      vert += 4;
    }
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  geo.setAttribute('normal', new BufferAttribute(new Float32Array(nor), 3));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  // Pull wall normals hard toward up — canyon stays mid-lit, never black.
  liftNormals(geo, 1.6);
  geo.computeBoundingSphere();
  return geo;
}

function buildLaneMarkers(track: Track, yOff: number, segs: number): BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  const idx: number[] = [];
  const hw = 0.65;
  let vert = 0;

  for (let i = 0; i < segs; i += 2) {
    const u0 = i / segs;
    const u1 = Math.min(1, (i + 0.85) / segs);
    const a = deckXZ(track, u0, -hw, yOff);
    const b = deckXZ(track, u0, hw, yOff);
    const c = deckXZ(track, u1, hw, yOff);
    const d = deckXZ(track, u1, -hw, yOff);
    const v = vert;
    pos.push(a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z, d.x, d.y, d.z);
    pushN(nor, a, 4);
    idx.push(v, v + 1, v + 2, v, v + 2, v + 3);
    vert += 4;
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  geo.setAttribute('normal', new BufferAttribute(new Float32Array(nor), 3));
  geo.setIndex(idx);
  flattenUpNormals(geo);
  return geo;
}

/** Thin longitudinal panel seams across the deck. */
function buildDeckSeams(track: Track, half: number, yOff: number, segs: number): BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  const idx: number[] = [];
  let vert = 0;
  const laterals = [-half * 0.72, -half * 0.42, half * 0.42, half * 0.72];
  const hw = 0.18;

  for (const lat of laterals) {
    for (let i = 0; i < segs; i += 3) {
      const u0 = i / segs;
      const u1 = Math.min(1, (i + 2.2) / segs);
      const a = deckXZ(track, u0, lat - hw, yOff);
      const b = deckXZ(track, u0, lat + hw, yOff);
      const c = deckXZ(track, u1, lat + hw, yOff);
      const d = deckXZ(track, u1, lat - hw, yOff);
      const v = vert;
      pos.push(a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z, d.x, d.y, d.z);
      pushN(nor, a, 4);
      idx.push(v, v + 1, v + 2, v, v + 2, v + 3);
      vert += 4;
    }
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  geo.setAttribute('normal', new BufferAttribute(new Float32Array(nor), 3));
  geo.setIndex(idx);
  flattenUpNormals(geo);
  return geo;
}

/** Alternating Wipeout-style kerb chevrons on the outer shoulders. */
function buildKerbChevrons(
  track: Track,
  inner: number,
  outer: number,
  yOff: number,
  segs: number,
  phase: 0 | 1,
): BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  const idx: number[] = [];
  let vert = 0;

  for (const side of [-1, 1] as const) {
    for (let i = 0; i < segs; i++) {
      if ((i + phase) % 2 !== 0) continue;
      const u0 = i / segs;
      const u1 = (i + 1) / segs;
      const a = deckXZ(track, u0, side * inner, yOff);
      const b = deckXZ(track, u0, side * outer, yOff);
      const c = deckXZ(track, u1, side * outer, yOff);
      const d = deckXZ(track, u1, side * inner, yOff);
      const v = vert;
      pos.push(a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z, d.x, d.y, d.z);
      pushN(nor, a, 4);
      idx.push(v, v + 1, v + 2, v, v + 2, v + 3);
      vert += 4;
    }
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  geo.setAttribute('normal', new BufferAttribute(new Float32Array(nor), 3));
  geo.setIndex(idx);
  flattenUpNormals(geo);
  return geo;
}

/** Direction chevrons on the racing corridor. */
function buildDirectionChevrons(track: Track, yOff: number, count: number): BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  const idx: number[] = [];
  let vert = 0;

  for (let i = 0; i < count; i++) {
    const u = (i + 0.5) / count;
    const tip = deckXZ(track, u + 0.004, 0, yOff);
    const bl = deckXZ(track, u - 0.003, -2.4, yOff);
    const br = deckXZ(track, u - 0.003, 2.4, yOff);
    const v = vert;
    pos.push(tip.x, tip.y, tip.z, bl.x, bl.y, bl.z, br.x, br.y, br.z);
    nor.push(0, 1, 0, 0, 1, 0, 0, 1, 0);
    idx.push(v, v + 1, v + 2);
    vert += 3;
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  geo.setAttribute('normal', new BufferAttribute(new Float32Array(nor), 3));
  geo.setIndex(idx);
  flattenUpNormals(geo);
  return geo;
}

/** Boost / weapon pads on the elevated centreline. */
function buildPads(
  track: Track,
  kind: 'boost' | 'weapon',
  yOff: number,
  mode: 'plate' | 'arrow' = 'plate',
): BufferGeometry {
  const pos: number[] = [];
  const nor: number[] = [];
  const idx: number[] = [];
  let vert = 0;
  const count = kind === 'boost' ? 8 : 5;
  const halfL = kind === 'boost' ? 4.2 : 3.4;
  const halfW = kind === 'boost' ? 3.6 : 3.0;
  const ds = halfL / track.length;

  for (let i = 0; i < count; i++) {
    const u = kind === 'boost' ? (i + 0.25) / count : (i + 0.55) / count;
    if (mode === 'plate') {
      const corners = [
        deckXZ(track, u - ds, -halfW, yOff),
        deckXZ(track, u - ds, halfW, yOff),
        deckXZ(track, u + ds, halfW, yOff),
        deckXZ(track, u + ds, -halfW, yOff),
      ];
      const v = vert;
      for (const p of corners) pos.push(p.x, p.y, p.z);
      pushN(nor, corners[0], 4);
      idx.push(v, v + 1, v + 2, v, v + 2, v + 3);
      vert += 4;
    } else {
      const tip = deckXZ(track, u + ds * 0.55, 0, yOff);
      const al = deckXZ(track, u - ds * 0.25, -halfW * 0.5, yOff);
      const ar = deckXZ(track, u - ds * 0.25, halfW * 0.5, yOff);
      const v = vert;
      pos.push(tip.x, tip.y, tip.z, al.x, al.y, al.z, ar.x, ar.y, ar.z);
      nor.push(0, 1, 0, 0, 1, 0, 0, 1, 0);
      idx.push(v, v + 1, v + 2);
      vert += 3;
    }
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  geo.setAttribute('normal', new BufferAttribute(new Float32Array(nor), 3));
  geo.setIndex(idx);
  flattenUpNormals(geo);
  geo.computeBoundingSphere();
  return geo;
}

export function createRaceFloor(track: Track): Group {
  const root = new Group();
  root.name = 'raceFloor';
  const segs = track.hasVerticalLoops ? 720 : SEG;
  const keepN = track.hasVerticalLoops;

  // Outer void apron — darker plate so the unlit neon grid above it pops.
  {
    const apron = new Mesh(buildFullStrip(track, APRON_HALF, -1.2, 120, true));
    const set = createCelMaterial({
      color: PAL.voidMid,
      rampColors: [PAL.voidDeep, PAL.voidMid, PAL.voidLift],
      outline: false,
      outlineWidthPx: 0,
      rimStrength: 0.1,
      edgeBias: 0,
      ambientStrength: 1.35,
      rampStops: [0.0, 0.2, 0.5, 0.85],
    });
    bothSides(set);
    applyCel(apron, set);
    apron.userData.skipPrepass = true;
    root.add(apron);
  }

  // Canyon walls — Hotline / HME cyan neon skirts under the deck lip.
  {
    const walls = new Mesh(buildCanyonWalls(track, DECK_HALF + 0.4, segs));
    const set = createCelMaterial({
      color: PAL.mesaRim,
      rampColors: [PAL.mesaDeep, PAL.mesaLit, PAL.mesaRim],
      outlineWidthPx: 1.5,
      rimStrength: 0.75,
      rimColor: PAL.gate,
      edgeBias: 0.35,
      ambientStrength: 1.25,
      rampStops: [0.0, 0.2, 0.48, 0.82],
    });
    bothSides(set);
    applyCel(walls, set);
    root.add(walls);
  }

  // Outer deck shoulders — cooler charcoal-cobalt frame for the riding band.
  {
    const deck = new Mesh(buildPanelDeck(track, DECK_HALF, 0.0, segs, keepN));
    const set = createCelMaterial({
      color: PAL.trackMid,
      rampColors: [PAL.trackDeep, PAL.trackMid, PAL.trackLit],
      outlineWidthPx: 1.7,
      rimStrength: 0.38,
      rimColor: PAL.trackCrest,
      specSize: 0.88,
      edgeBias: 0.75,
      ambientStrength: 1.18,
      rampStops: [0.0, 0.28, 0.58, 0.88],
    });
    bothSides(set);
    applyCel(deck, set);
    root.add(deck);
  }

  // Centre riding band — bright cobalt corridor (kept lighter than shoulders).
  {
    const mid = new Mesh(buildFullStrip(track, DECK_HALF * 0.62, 0.02, segs, false, keepN));
    const set = createCelMaterial({
      color: PAL.trackLit,
      rampColors: [PAL.trackLit, PAL.trackCrest, PAL.foamShade],
      outlineWidthPx: 1.1,
      rimStrength: 0.55,
      rimColor: PAL.foam,
      specSize: 0.94,
      edgeBias: 0.45,
      ambientStrength: 1.75,
      rampStops: [0.0, 0.12, 0.42, 0.78],
    });
    bothSides(set);
    applyCel(mid, set);
    root.add(mid);
  }

  // Panel seams — deep grooves so plates read without washing the blue.
  {
    const seams = new Mesh(buildDeckSeams(track, DECK_HALF, 0.03, segs));
    const set = createCelMaterial({
      color: PAL.trackDeep,
      rampColors: [PAL.ink, PAL.trackDeep, PAL.trackMid],
      outlineWidthPx: 0.75,
      rimStrength: 0.12,
      edgeBias: 0.25,
      ambientStrength: 0.9,
      rampStops: [0.0, 0.3, 0.6, 0.9],
    });
    bothSides(set);
    applyCel(seams, set);
    root.add(seams);
  }

  {
    const ticks = new Mesh(buildLaneMarkers(track, 0.08, segs));
    const set = createCelMaterial({
      color: PAL.raceLine,
      rampColors: [PAL.gate, PAL.raceLine, PAL.raceLineGlow],
      outlineWidthPx: 1.3,
      rimStrength: 0.55,
      edgeBias: 0.6,
    });
    bothSides(set);
    applyCel(ticks, set);
    root.add(ticks);
  }

  // Direction chevrons along the corridor
  {
    const chevs = new Mesh(buildDirectionChevrons(track, 0.09, 48));
    const set = createCelMaterial({
      color: PAL.raceLineGlow,
      rampColors: [PAL.gate, PAL.raceLine, PAL.raceLineGlow],
      outlineWidthPx: 1.1,
      rimStrength: 0.5,
      edgeBias: 0.55,
      ambientStrength: 1.0,
    });
    bothSides(set);
    applyCel(chevs, set);
    root.add(chevs);
  }

  // Boost pads (magenta) + weapon pads (gold), with contrasting arrows
  {
    const boost = new Mesh(buildPads(track, 'boost', 0.11, 'plate'));
    const set = createCelMaterial({
      color: PAL.boostPad,
      rampColors: [PAL.boost, PAL.boostPad, PAL.boostHot],
      outlineWidthPx: 1.6,
      rimStrength: 0.75,
      rimColor: PAL.boostHot,
      edgeBias: 0.7,
      ambientStrength: 1.1,
      flareMask: 0,
    });
    bothSides(set);
    applyCel(boost, set);
    root.add(boost);

    const boostArrow = new Mesh(buildPads(track, 'boost', 0.14, 'arrow'));
    const setA = createCelMaterial({
      color: PAL.hudPaper,
      rampColors: [PAL.foamShade, PAL.hudPaper, PAL.foam],
      outlineWidthPx: 1.0,
      rimStrength: 0.4,
      ambientStrength: 1.1,
      flareMask: 0,
    });
    bothSides(setA);
    applyCel(boostArrow, setA);
    root.add(boostArrow);
  }
  {
    const weapons = new Mesh(buildPads(track, 'weapon', 0.12, 'plate'));
    const set = createCelMaterial({
      color: PAL.weaponPad,
      rampColors: [PAL.buoy, PAL.weaponPad, PAL.sun],
      outlineWidthPx: 1.6,
      rimStrength: 0.7,
      rimColor: PAL.sun,
      edgeBias: 0.7,
      ambientStrength: 1.05,
      flareMask: 0,
    });
    bothSides(set);
    applyCel(weapons, set);
    root.add(weapons);

    const weapArrow = new Mesh(buildPads(track, 'weapon', 0.15, 'arrow'));
    const setA = createCelMaterial({
      color: PAL.ink,
      rampColors: [PAL.ink, PAL.inkSoft, PAL.hudDim],
      outlineWidthPx: 1.0,
      rimStrength: 0.35,
      ambientStrength: 1.0,
      flareMask: 0,
    });
    bothSides(setA);
    applyCel(weapArrow, setA);
    root.add(weapArrow);
  }

  {
    const rails = new Mesh(buildEdgeRails(track, DECK_HALF * 0.99, 0.04, segs));
    const set = createCelMaterial({
      color: PAL.wall,
      rampColors: [PAL.trackDeep, PAL.wall, PAL.trackCrest],
      outlineWidthPx: 2.1,
      rimStrength: 0.65,
      rimColor: PAL.trackCrest,
      specSize: 0.86,
      ambientStrength: 1.2,
      rampStops: [0.0, 0.18, 0.45, 0.8],
    });
    bothSides(set);
    applyCel(rails, set);
    root.add(rails);
  }

  // Rail top accent — hot cyan energy strip.
  {
    const cap = new Mesh(buildShoulders(track, DECK_HALF * 0.99, DECK_HALF + 0.55, 1.22, segs, keepN));
    const set = createCelMaterial({
      color: PAL.trackEdge,
      rampColors: [PAL.gate, PAL.trackEdge, PAL.foam],
      outlineWidthPx: 1.0,
      rimStrength: 0.7,
      rimColor: PAL.foam,
      edgeBias: 0.55,
      ambientStrength: 1.15,
      flareMask: 0.35,
    });
    bothSides(set);
    applyCel(cap, set);
    root.add(cap);
  }

  {
    const shoulder = new Mesh(buildShoulders(track, DECK_HALF, DECK_HALF + 3.6, 0.06, segs, keepN));
    const set = createCelMaterial({
      color: PAL.gate,
      rampColors: [PAL.trackMid, PAL.trackEdge, PAL.gate],
      outlineWidthPx: 1.15,
      rimStrength: 0.55,
      edgeBias: 0.4,
      ambientStrength: 1.05,
    });
    bothSides(set);
    applyCel(shoulder, set);
    root.add(shoulder);
  }

  // Alternating kerb chevrons — vermilion / ice for classic AG contrast.
  {
    const kerbA = new Mesh(buildKerbChevrons(track, DECK_HALF + 0.15, DECK_HALF + 3.4, 0.075, segs, 0));
    const setA = createCelMaterial({
      color: PAL.warn,
      rampColors: [PAL.hull0, PAL.warn, PAL.boostHot],
      outlineWidthPx: 0.95,
      rimStrength: 0.55,
      rimColor: PAL.boostHot,
      edgeBias: 0.45,
      ambientStrength: 1.15,
    });
    bothSides(setA);
    applyCel(kerbA, setA);
    root.add(kerbA);

    const kerbB = new Mesh(buildKerbChevrons(track, DECK_HALF + 0.15, DECK_HALF + 3.4, 0.075, segs, 1));
    const setB = createCelMaterial({
      color: PAL.foam,
      rampColors: [PAL.foamShade, PAL.hudPaper, PAL.foam],
      outlineWidthPx: 0.95,
      rimStrength: 0.5,
      rimColor: PAL.foam,
      edgeBias: 0.45,
      ambientStrength: 1.2,
    });
    bothSides(setB);
    applyCel(kerbB, setB);
    root.add(kerbB);
  }

  return root;
}
