/**
 * Off-track mountain contact → wreck.
 * Soft apron drag stays in shipPhysics; this is the hard kill when you hit the rocks.
 */

import { CONFIG } from '../core/config';
import type { GameContext, Subsystem } from '../core/types';
import { wreckRacer } from './hull';
import {
  getMountainField,
  sampleMountainHeight,
  type MountainField,
} from '../world/mountainTerrain';

export class TerrainWreckSystem implements Subsystem {
  readonly name = 'terrainWreck';
  readonly order = 54;

  private field: MountainField | null = null;

  init(ctx: GameContext) {
    this.field = getMountainField(ctx.scene);
  }

  update(ctx: GameContext) {
    if (ctx.phase !== 'racing') return;
    if (!this.field) this.field = getMountainField(ctx.scene);
    const field = this.field;
    if (!field) return;

    const lateralLimit = CONFIG.race.mountainWreckLateral;
    const slack = CONFIG.race.mountainContactSlack;
    const { height, size, worldHalf } = field;

    for (const r of ctx.racers) {
      if (r.destroyed || r.finished) continue;
      const pos = r.state.position;
      const proj = ctx.track.project(pos);
      if (Math.abs(proj.lateral) < lateralLimit) continue;

      const mtnY = sampleMountainHeight(height, size, worldHalf, pos.x, pos.z);
      // Ship origin sits near deck; contact when the hull digs into the massif.
      if (pos.y > mtnY + slack) continue;

      wreckRacer(r, ctx.raceTime);
      if (r.isPlayer) ctx.cameraRig?.addShake(1.1);
    }
  }
}
