/**
 * Mountain relief around the circuit — simplified from BMX_Racer's heightfield.
 *
 * Noise stack (domain warp → lateral → ridged crests → billow foothills → detail)
 * plus a kernel-weighted corridor prior so the massif follows track elevation
 * without medial-axis seams at switchbacks. The riding deck is punched into a
 * canyon so mountains never pierce the cel floor.
 */

import {
  BufferAttribute,
  BufferGeometry,
  DoubleSide,
  Group,
  Mesh,
  Vector3,
} from 'three';
import { Noise2D } from '../core/noise2d';
import { clamp, lerp, smoothstep } from '../core/mathx';
import { PAL } from '../core/palette';
import { CONFIG } from '../core/config';
import { applyCel, createCelMaterial, type CelMaterialSet } from '../render/celMaterial';
import type { Track } from '../race/track';

const GRID = 144;
const WORLD_HALF = 500;
const DECK_HALF = CONFIG.race.deckHalf;
const DECK_CLEAR = DECK_HALF + 14;
/** Full corridor pull inside this radius. */
const CORRIDOR_CORE = DECK_HALF + 36;
/** Prior fades out by this distance. */
const CORRIDOR_MAX = 170;
const CORRIDOR_KERNEL = 150;
const CORRIDOR_PULL = 0.78;
const CANYON_DROP = 14;
const ROUTE_STRIDE_M = 10;

type CorridorField = {
  dist: Float32Array;
  targetHeight: Float32Array;
};

function bothSides(set: CelMaterialSet) {
  set.main.side = DoubleSide;
  set.prepass.side = DoubleSide;
  if (set.outline) set.outline.side = DoubleSide;
}

function corridorWeight(d: number): number {
  return 1 - smoothstep(CORRIDOR_CORE, CORRIDOR_MAX, d);
}

/**
 * Splat the centreline into distance + kernel-weighted target height
 * (BMX corridor prior — avoids switchback medial-axis walls).
 */
function buildCorridorField(track: Track, size: number, worldHalf: number): CorridorField {
  const n = size * size;
  const dist = new Float32Array(n).fill(CORRIDOR_MAX);
  const targetHeight = new Float32Array(n);
  const sumW = new Float32Array(n);
  const sumWH = new Float32Array(n);

  const mps = (worldHalf * 2) / size;
  const w2g = (v: number) => (v + worldHalf) / mps;
  const g2w = (i: number) => -worldHalf + i * mps;
  const R = CORRIDOR_KERNEL;
  const R2 = R * R;
  const rTexels = Math.ceil(R / mps);

  const samples = Math.max(48, Math.ceil(track.length / ROUTE_STRIDE_M));
  const _tp = {
    position: new Vector3(),
    tangent: new Vector3(0, 0, 1),
    curvature: 0,
    u: 0,
  };

  for (let s = 0; s < samples; s++) {
    const u = s / samples;
    track.sample(u, _tp);
    const rx = _tp.position.x;
    const rz = _tp.position.z;
    const rh = track.heightAt(u);

    const gcx = w2g(rx);
    const gcz = w2g(rz);
    const ix0 = Math.max(0, Math.floor(gcx) - rTexels);
    const ix1 = Math.min(size - 1, Math.ceil(gcx) + rTexels);
    const iz0 = Math.max(0, Math.floor(gcz) - rTexels);
    const iz1 = Math.min(size - 1, Math.ceil(gcz) + rTexels);

    for (let iz = iz0; iz <= iz1; iz++) {
      const wz = g2w(iz) - rz;
      const wz2 = wz * wz;
      const row = iz * size;
      for (let ix = ix0; ix <= ix1; ix++) {
        const wx = g2w(ix) - rx;
        const d2 = wx * wx + wz2;
        if (d2 >= R2) continue;
        const i = row + ix;
        const d = Math.sqrt(d2);
        if (d < dist[i]!) dist[i] = d;
        const uu = 1 - d2 / R2;
        const w = uu * uu;
        sumW[i]! += w;
        sumWH[i]! += w * rh;
      }
    }
  }

  for (let i = 0; i < n; i++) {
    const w = sumW[i]!;
    targetHeight[i] = w > 1e-6 ? sumWH[i]! / w : 0;
  }

  return { dist, targetHeight };
}

function meanTrackHeight(track: Track): number {
  let sum = 0;
  const steps = 64;
  for (let i = 0; i < steps; i++) sum += track.heightAt(i / steps);
  return sum / steps;
}

/** Domain-warped massif + corridor prior + deck canyon punch. */
function buildHeights(track: Track, size: number, worldHalf: number): Float32Array {
  const seed = `ws-mtn:${track.layout.id}`;
  const corridor = buildCorridorField(track, size, worldHalf);
  const meanH = meanTrackHeight(track);

  const nWarpA = new Noise2D(`${seed}:warpA`);
  const nWarpB = new Noise2D(`${seed}:warpB`);
  const nLateral = new Noise2D(`${seed}:lateral`);
  const nRidge = new Noise2D(`${seed}:ridge`);
  const nBillow = new Noise2D(`${seed}:billow`);
  const nDetail = new Noise2D(`${seed}:detail`);
  const nMicro = new Noise2D(`${seed}:micro`);

  const height = new Float32Array(size * size);
  const mps = (worldHalf * 2) / size;

  for (let iz = 0; iz < size; iz++) {
    const z = -worldHalf + iz * mps;
    const row = iz * size;
    for (let ix = 0; ix < size; ix++) {
      const x = -worldHalf + ix * mps;
      const i = row + ix;
      const d = corridor.dist[i]!;
      const target = corridor.targetHeight[i]!;
      const hasTarget = d < CORRIDOR_MAX - 0.5;

      // Domain warp (scaled for ~1 km arena vs BMX's 4 km).
      const wax = nWarpA.fbm(x * 0.0017, z * 0.0017, 4);
      const waz = nWarpA.fbm(x * 0.0017 + 31.7, z * 0.0017 + 13.1, 4);
      const ax = x + wax * 55;
      const az = z + waz * 55;
      const wbx = nWarpB.fbm(ax * 0.0064 + 5.3, az * 0.0064 + 9.1, 3);
      const wbz = nWarpB.fbm(ax * 0.0064 + 17.9, az * 0.0064 + 2.7, 3);
      const ux = ax + wbx * 22;
      const uz = az + wbz * 22;

      // Base sits near track elevation; rises into mountains off-corridor.
      const base = (hasTarget ? target : meanH) + 4;
      const riseMask = smoothstep(DECK_CLEAR + 8, 110, d);
      const highMask = smoothstep(DECK_CLEAR + 24, 140, d);
      const lowMask = 1 - smoothstep(DECK_CLEAR + 10, 90, d);

      const lateral = nLateral.fbm(ux * 0.0027, uz * 0.0027, 5) * 48 * riseMask;
      const r = nRidge.ridged(ux * 0.0054, uz * 0.0054, 6, 2.03, 0.5, 1.0);
      const ridge = (r - 0.38) * 95 * highMask;
      const bl = nBillow.billow(ux * 0.0084, uz * 0.0084, 5);
      const billow = bl * 28 * (0.35 + 0.65 * lowMask) * riseMask;

      const d1 = nDetail.fbm(ux * 0.032, uz * 0.032, 4) * 6.5;
      const d2 = nMicro.fbm(x * 0.09, z * 0.09, 3) * 1.6;

      let low = base + lateral + ridge + billow;

      const cw = corridorWeight(d);
      if (cw > 0.0005 && hasTarget) {
        low = lerp(low, target, cw * CORRIDOR_PULL);
      }

      // Punch the riding corridor into a canyon under the cel deck.
      const punch = 1 - smoothstep(DECK_CLEAR - 2, DECK_CLEAR + 22, d);
      if (punch > 0.001 && hasTarget) {
        low = lerp(low, target - CANYON_DROP, punch);
      }

      let h = low + (d1 + d2) * (1 - 0.25 * cw);

      // Calm relief near the map edge so the void apron meets quietly.
      const m = Math.max(Math.abs(x), Math.abs(z));
      const edge = smoothstep(worldHalf * 0.78, worldHalf, m);
      if (edge > 0) h = lerp(h, meanH - 6, edge * 0.85);

      height[i] = h;
    }
  }

  return height;
}

function buildTerrainMesh(height: Float32Array, size: number, worldHalf: number): BufferGeometry {
  const mps = (worldHalf * 2) / size;
  const vertCount = size * size;
  const pos = new Float32Array(vertCount * 3);

  for (let iz = 0; iz < size; iz++) {
    const z = -worldHalf + iz * mps;
    for (let ix = 0; ix < size; ix++) {
      const x = -worldHalf + ix * mps;
      const i = iz * size + ix;
      const o = i * 3;
      pos[o] = x;
      pos[o + 1] = height[i]!;
      pos[o + 2] = z;
    }
  }

  const idx: number[] = [];
  for (let iz = 0; iz < size - 1; iz++) {
    for (let ix = 0; ix < size - 1; ix++) {
      const a = iz * size + ix;
      const b = a + 1;
      const c = a + size;
      const d = c + 1;
      idx.push(a, c, b, b, c, d);
    }
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(pos, 3));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  geo.computeBoundingSphere();
  return geo;
}

/**
 * Soft upward bias so steep faces don't fall into the darkest cel band.
 */
function liftNormals(geo: BufferGeometry, upBias = 0.42) {
  const nor = geo.getAttribute('normal');
  if (!nor) return;
  for (let i = 0; i < nor.count; i++) {
    let nx = nor.getX(i);
    let ny = nor.getY(i) + upBias;
    let nz = nor.getZ(i);
    const len = Math.hypot(nx, ny, nz) || 1;
    nor.setXYZ(i, nx / len, ny / len, nz / len);
  }
  nor.needsUpdate = true;
}

/** Cel-shaded mountain mesh group for the current track. */
export function createMountainTerrain(track: Track): Group {
  const root = new Group();
  root.name = 'mountainTerrain';

  const height = buildHeights(track, GRID, WORLD_HALF);
  const geo = buildTerrainMesh(height, GRID, WORLD_HALF);
  liftNormals(geo, 0.48);

  const mesh = new Mesh(geo);
  const set = createCelMaterial({
    color: PAL.mesaMid,
    rampColors: [PAL.mesaDeep, PAL.mesaMid, PAL.mesaLit, PAL.mesaCrest],
    outlineWidthPx: 1.4,
    rimStrength: 0.55,
    rimColor: PAL.mesaRim,
    edgeBias: 0.4,
    ambientStrength: 1.15,
    rampStops: [0.0, 0.18, 0.45, 0.78],
    flareMask: 0.15,
  });
  bothSides(set);
  applyCel(mesh, set);
  mesh.frustumCulled = true;
  root.add(mesh);

  // Keep the heightfield for runtime collision (off-track → mountain wreck).
  root.userData.mountainField = {
    height,
    size: GRID,
    worldHalf: WORLD_HALF,
  } satisfies MountainField;

  return root;
}

export type MountainField = {
  height: Float32Array;
  size: number;
  worldHalf: number;
};

export function getMountainField(scene: { getObjectByName(name: string): { userData: Record<string, unknown> } | undefined }): MountainField | null {
  const root = scene.getObjectByName('mountainTerrain');
  const field = root?.userData?.mountainField as MountainField | undefined;
  return field?.height ? field : null;
}

/** Exported for tests / harness. */
export function sampleMountainHeight(
  height: Float32Array,
  size: number,
  worldHalf: number,
  x: number,
  z: number,
): number {
  const mps = (worldHalf * 2) / size;
  const gx = clamp((x + worldHalf) / mps, 0, size - 1.0001);
  const gz = clamp((z + worldHalf) / mps, 0, size - 1.0001);
  const x0 = gx | 0;
  const z0 = gz | 0;
  const fx = gx - x0;
  const fz = gz - z0;
  const i0 = z0 * size + x0;
  const i1 = i0 + size;
  const h00 = height[i0]!;
  const h10 = height[i0 + 1]!;
  const h01 = height[i1]!;
  const h11 = height[i1 + 1]!;
  return lerp(lerp(h00, h10, fx), lerp(h01, h11, fx), fz);
}

export { GRID as MOUNTAIN_GRID, WORLD_HALF as MOUNTAIN_WORLD_HALF };
