/**
 * Open-world anti-grav physics — no hard walls.
 * Free XZ flight; hover spring follows deck relief near the centreline and
 * falls back to the void plane when far off-line. Leaving the ribbon applies
 * soft off-track drag + speed cap (see CONFIG.race.offTrack*).
 * Racing line is a hint only; wrong-way is owned by RaceState.
 */

import { Vector3 } from 'three';
import { CONFIG } from '../core/config';
import { clamp01, damp } from '../core/mathx';
import type { InputState } from '../core/input';
import { MOBILE_ASSIST } from '../core/mobileAssist';
import type { HullIntegrity, ShipState, TrackAPI, WeaponKind } from '../core/types';
import { nitroAccel, nitroSpeedMul, tickNitroBurn } from '../nitro/charge';
import type { Track } from '../race/track';
import { getShipTune } from '../race/raceSettings';
import { hullBoostScale, hullSteerMods, hullThrottleScale } from './hull';

const _fwd = new Vector3();
const _right = new Vector3();
const _nSurf = new Vector3(0, 1, 0);
const _deckPt = new Vector3();
const _tp = {
  position: new Vector3(),
  tangent: new Vector3(0, 0, 1),
  curvature: 0,
  u: 0,
};

export function createShipState(): ShipState {
  return {
    position: new Vector3(),
    velocity: new Vector3(),
    heading: 0,
    forwardSpeed: 0,
    lateralSpeed: 0,
    speedFrac: 0,
    pitch: 0,
    roll: 0,
    hoverGap: CONFIG.ship.hoverHeight,
    airborne: false,
    airTime: 0,
    airbraking: false,
    boostMeter: 0.35,
    boosting: false,
    appliedThrottle: 0,
    shieldTime: 0,
    weapon: 'none',
    weaponAmmo: 0,
    hp: 100,
    maxHp: 100,
    hitFlash: 0,
    landingImpact: 0,
    nitroTime: 0,
  };
}

export function stepShip(
  state: ShipState,
  controls: InputState,
  track: TrackAPI,
  dt: number,
  opts?: { combat?: boolean; hull?: HullIntegrity; mobileAssist?: boolean },
) {
  const C = getShipTune();
  dt = Math.min(dt, 0.05);
  const assist = !!opts?.mobileAssist;

  const hull = opts?.hull;
  const thrScale = hull ? hullThrottleScale(hull) : 1;
  const steerMods = hull ? hullSteerMods(hull) : { scale: 1, bias: 0 };
  const boostScale = hull ? hullBoostScale(hull) : 1;

  const thrRate = controls.throttle > state.appliedThrottle ? C.throttleUpRate : C.throttleDownRate;
  state.appliedThrottle = damp(
    state.appliedThrottle,
    controls.throttle * thrScale,
    thrRate,
    dt,
  );

  const airL = controls.airbrakeL;
  const airR = controls.airbrakeR;
  state.airbraking = airL || airR || controls.brake > 0.2;

  const wantBoost = controls.boost && state.boostMeter > 0.02;
  state.boosting = wantBoost;
  if (wantBoost) state.boostMeter = Math.max(0, state.boostMeter - C.boostDrainRate * dt);
  else state.boostMeter = Math.min(C.boostMax, state.boostMeter + C.boostChargeRate * dt * 0.35);

  const speed = state.velocity.length();
  const speedT = clamp01(speed / C.topSpeed);
  let turnAuth = C.turnRateLow + (C.turnRateHigh - C.turnRateLow) * speedT;
  if (assist) turnAuth *= MOBILE_ASSIST.turnMul;
  // WaveKill convention: positive steer decreases heading (screen-right turn).
  let steer = controls.steer * steerMods.scale + steerMods.bias;
  const airSteer = assist ? MOBILE_ASSIST.airbrakeSteer : 0.85;
  if (airL && !airR) steer -= airSteer;
  if (airR && !airL) steer += airSteer;
  const yawGain = state.airbraking ? (assist ? 1.2 : C.airbrakeYawGain) : 1;
  const yawRate = -steer * turnAuth * yawGain;
  state.heading += yawRate * dt;

  _fwd.set(Math.sin(state.heading), 0, Math.cos(state.heading));
  _right.set(_fwd.z, 0, -_fwd.x);

  // Off-track: project before thrust so leaving the ribbon bleeds speed immediately.
  const tr = track as Track;
  const projPre = tr.project(state.position);
  const DECK_HALF = CONFIG.race.deckHalf;
  const RACE = CONFIG.race;
  const offRaw = Math.abs(projPre.lateral) - (DECK_HALF + RACE.offTrackMargin);
  const offTrack = clamp01(offRaw / Math.max(1e-3, RACE.offTrackFade));

  let thrust = state.appliedThrottle * C.thrust;
  if (controls.brake > 0) thrust -= controls.brake * C.reverseThrust;
  if (state.boosting) thrust += C.boostForce * C.boostThrustMul * boostScale;
  if (airL && airR) thrust *= 0.35;
  thrust += nitroAccel(state, C.mass) * C.mass;
  // Void has no AG rail — throttle authority collapses off the ribbon.
  if (offTrack > 0) {
    const thrustFloor = assist ? 0.55 : RACE.offTrackThrustMul;
    thrust *= 1 - offTrack * (1 - thrustFloor);
  }

  state.velocity.x += _fwd.x * (thrust / C.mass) * dt;
  state.velocity.z += _fwd.z * (thrust / C.mass) * dt;

  const v = Math.hypot(state.velocity.x, state.velocity.z);
  if (v > 1e-4) {
    const drag = C.dragLinear * v + C.dragQuadratic * v * v;
    let scale = Math.max(0, 1 - (drag * dt) / v);
    if (offTrack > 0) {
      const dragMul = assist ? 0.55 : 1;
      scale *= Math.exp(-RACE.offTrackDrag * offTrack * dragMul * dt);
    }
    state.velocity.x *= scale;
    state.velocity.z *= scale;
  }

  const speedMulFloor = assist ? 0.55 : RACE.offTrackSpeedMul;
  const cap =
    (state.boosting || state.nitroTime > 0 ? C.boostTopSpeed : C.topSpeed) *
    nitroSpeedMul(state) *
    (1 - offTrack * (1 - speedMulFloor));
  const v2 = Math.hypot(state.velocity.x, state.velocity.z);
  if (v2 > cap) {
    state.velocity.x = (state.velocity.x / v2) * cap;
    state.velocity.z = (state.velocity.z / v2) * cap;
  }
  tickNitroBurn(state, dt);

  // Lateral grip in hull frame
  const lat = state.velocity.x * _right.x + state.velocity.z * _right.z;
  const grip = state.airbraking ? C.airbrakeGrip : C.lateralGrip;
  const newLat = lat * Math.exp(-grip * dt);
  state.velocity.x += _right.x * (newLat - lat);
  state.velocity.z += _right.z * (newLat - lat);

  state.position.x += state.velocity.x * dt;
  state.position.z += state.velocity.z * dt;

  // Soft hover: hold a fixed gap above the *banked* deck across the riding
  // surface. Centreline-only height lets you tunnel under the outer rail in turns.
  // Vertical loops switch to surface-normal stick so the craft can go inverted.
  const projHover = tr.project(state.position);
  const signedLat = projHover.lateral;
  const lateral = Math.abs(signedLat);
  const centerY = typeof tr.heightAt === 'function' ? tr.heightAt(projHover.u) : 0;
  const deckY =
    typeof tr.surfaceHeightAt === 'function'
      ? tr.surfaceHeightAt(projHover.u, signedLat)
      : centerY;
  // 1 on the deck, fades only after leaving the riding surface + short apron.
  const onDeck = lateral <= DECK_HALF ? 1 : Math.exp(-(lateral - DECK_HALF) / 8);
  // Mild centreline bias for grade / camber (not for hover height).
  const follow = Math.exp(-lateral / Math.max(24, DECK_HALF * 1.6));
  const trackLen = Math.max(1, tr.length);
  // Lookahead grade — nose anticipates the next crest/drop.
  const lookDist = Math.max(6, Math.abs(state.forwardSpeed) * 0.32);
  const lookU = projHover.u + lookDist / trackLen;
  const gradeNow = tr.sample(projHover.u, _tp).tangent.y;
  const gradeAhead = tr.sample(lookU, _tp).tangent.y;
  const grade = (gradeNow * 0.4 + gradeAhead * 0.6) * onDeck;
  const gradeDeriv = ((gradeAhead - gradeNow) / lookDist) * onDeck;
  // Deck vertical velocity if glued to the racing line (bank roll included).
  let bank = 0;
  if (typeof tr.bankAt === 'function') bank = tr.bankAt(projHover.u);
  const deckVy =
    (gradeNow + state.lateralSpeed * Math.sin(bank) * 0.15) * state.forwardSpeed * onDeck;

  const looping =
    tr.hasVerticalLoops && typeof tr.surfaceNormalAt === 'function';
  let nY = 1;
  if (looping) {
    tr.surfaceNormalAt(projHover.u, _nSurf);
    nY = _nSurf.y;
  }
  const onLoop = looping && nY < 0.88;

  // Grade accel: downhill free speed, uphill drag — makes relief matter.
  // On loops, push along the surface tangent's horizontal instead.
  const gAccel = -grade * C.gravity * C.gradeAccel;
  state.velocity.x += _fwd.x * gAccel * dt;
  state.velocity.z += _fwd.z * gAccel * dt;

  // Mild camber: banked deck pulls toward the inside when near the line.
  if (typeof tr.bankAt === 'function' && !onLoop) {
    const camber = -bank * C.gravity * C.bankCamber * follow;
    state.velocity.x += _right.x * camber * dt;
    state.velocity.z += _right.z * camber * dt;
  }

  if (onLoop) {
    // Stick to the ribbon along the surface normal (supports inverted apex).
    tr.linePoint(projHover.u, signedLat, _deckPt);
    const hover = C.hoverHeight;
    const tx = _deckPt.x + _nSurf.x * hover;
    const ty = _deckPt.y + _nSurf.y * hover;
    const tz = _deckPt.z + _nSurf.z * hover;
    const ex = state.position.x - tx;
    const ey = state.position.y - ty;
    const ez = state.position.z - tz;
    const gapErr = ex * _nSurf.x + ey * _nSurf.y + ez * _nSurf.z;
    const vn =
      state.velocity.x * _nSurf.x + state.velocity.y * _nSurf.y + state.velocity.z * _nSurf.z;
    // Stiffer glue through the loop so you don't fall out at the apex.
    const stiff = C.hoverStiffness * 1.55;
    const dampN = C.hoverDamping * 1.25;
    const an = -stiff * gapErr * onDeck - dampN * vn;
    const dvx = _nSurf.x * an * dt;
    const dvy = _nSurf.y * an * dt;
    const dvz = _nSurf.z * an * dt;
    state.velocity.x += dvx;
    state.velocity.y += dvy;
    state.velocity.z += dvz;
    // Weak world gravity so the AG rail still reads as "sticking", not freefall.
    state.velocity.y -= C.gravity * 0.12 * dt;
    // XZ already stepped earlier — apply only the new normal impulse there.
    state.position.x += dvx;
    state.position.z += dvz;
    state.position.y += state.velocity.y * dt;
    // Snap soft if we punched through the deck.
    if (gapErr < -0.4 * onDeck) {
      state.position.x -= _nSurf.x * gapErr;
      state.position.y -= _nSurf.y * gapErr;
      state.position.z -= _nSurf.z * gapErr;
      const vDot = Math.min(0, vn);
      state.velocity.x -= _nSurf.x * vDot;
      state.velocity.y -= _nSurf.y * vDot;
      state.velocity.z -= _nSurf.z * vDot;
    }
    state.hoverGap = gapErr + hover;
    const wasAir = state.airborne;
    const prevAirTime = state.airTime;
    state.airborne = Math.abs(gapErr) > 1.4;
    state.airTime = state.airborne ? state.airTime + dt : 0;
    state.landingImpact =
      wasAir && !state.airborne && prevAirTime > 0.18
        ? Math.min(5, prevAirTime * 3.4)
        : 0;
  } else {
    // Full hover gap above banked deck on-circuit; blend to void hover off apron.
    const targetY = C.hoverHeight + deckY * onDeck;
    const gapErr = state.position.y - targetY;
    // Crest loft: convex peaks soften the spring so the craft pops airborne.
    const crestLoft = gradeDeriv < -0.009 && Math.abs(state.forwardSpeed) > 32 ? 1 : 0;
    let stiff = C.hoverStiffness * (crestLoft ? 0.28 : 1);
    let dampY = C.hoverDamping * (crestLoft ? 0.55 : 1);
    // On steep drops, don't slam the spring — let gravity carry the dive.
    if (grade < -0.08 && gapErr < 0.4) {
      stiff *= 0.45;
      dampY *= 0.7;
    }
    const ay = -stiff * gapErr - dampY * (state.velocity.y - deckVy * (1 - crestLoft * 0.7));
    // Extra loft impulse over crests at speed.
    if (crestLoft && gapErr > -0.15) {
      state.velocity.y += Math.min(3.8, Math.abs(state.forwardSpeed) * 0.02) * dt * 10;
    }
    state.velocity.y += ay * dt;
    // Gravity always present so airtime arcs read.
    state.velocity.y -= C.gravity * 0.35 * dt;
    state.position.y += state.velocity.y * dt;

    // Anti-tunnel: never drop under the banked ribbon while still over its footprint
    // (or cutting the inside of an elevated corner beside it).
    const guardW = DECK_HALF + RACE.offTrackMargin + 6;
    if (lateral < guardW * 2.2) {
      const guard = clamp01(1 - lateral / (guardW * 2.2));
      // Prefer the local banked surface; fall back to centreline so inside cuts
      // can't sink under a raised outer arc.
      const floorDeck = Math.max(deckY * onDeck, centerY * guard * 0.92);
      const floor = C.hoverHeight * 0.65 + floorDeck;
      if (state.position.y < floor) {
        state.position.y = floor;
        if (state.velocity.y < deckVy) state.velocity.y = deckVy;
      }
    }

    state.hoverGap = state.position.y - deckY * onDeck;
    const wasAir = state.airborne;
    const prevAirTime = state.airTime;
    const closeSpeed = deckVy - state.velocity.y;
    state.airborne = Math.abs(gapErr) > 1.05 || (crestLoft === 1 && gapErr > 0.35);
    state.airTime = state.airborne ? state.airTime + dt : 0;
    // Landing from airtime or hard vertical closure — feeds chase-cam shake.
    let land = 0;
    if (wasAir && !state.airborne && prevAirTime > 0.18) {
      land = Math.min(5, prevAirTime * 3.4 + Math.max(0, closeSpeed) * 0.35);
    } else if (!state.airborne && closeSpeed > 6.5 && Math.abs(gapErr) < 1.2) {
      land = Math.min(3.2, (closeSpeed - 6.5) * 0.45);
    }
    state.landingImpact = land;
  }

  // Soft utility pads (shield / turbo) — rockets come from track rocket boxes.
  if (opts?.combat) {
    const proj = projHover;
    if (Math.abs(proj.lateral) < 12 && state.weapon === 'none' && state.weaponAmmo <= 0) {
      const u = proj.u;
      for (let i = 0; i < 5; i++) {
        const pu = (i + 0.55) / 5;
        if (Math.abs(((u - pu + 0.5) % 1) - 0.5) < 0.012) {
          const weapons: WeaponKind[] = ['shield', 'turbo'];
          state.weapon = weapons[Math.floor(Math.abs(state.position.x * 7)) % weapons.length]!;
          state.weaponAmmo = 1;
        }
      }
    }
  }
  // Soft boost recharge near racing line
  {
    const proj = tr.project(state.position);
    if (Math.abs(proj.lateral) < 10) {
      state.boostMeter = Math.min(C.boostMax, state.boostMeter + 0.35 * dt);
    }
  }

  // Missiles are fired by RocketField (lock-gated). Mines stay a stub pickup.
  if (controls.firePressed && state.weapon !== 'none' && state.weaponAmmo > 0) {
    if (state.weapon === 'missile' || state.weapon === 'mines') {
      // no-op here
    } else if (state.weapon === 'shield') {
      state.shieldTime = 3;
      state.weaponAmmo -= 1;
      if (state.weaponAmmo <= 0) state.weapon = 'none';
    } else if (state.weapon === 'turbo') {
      state.boostMeter = 1;
      state.boosting = true;
      state.weaponAmmo -= 1;
      if (state.weaponAmmo <= 0) state.weapon = 'none';
    }
  }
  if (state.shieldTime > 0) state.shieldTime = Math.max(0, state.shieldTime - dt);
  if (state.hitFlash > 0) state.hitFlash = Math.max(0, state.hitFlash - dt);

  _fwd.set(Math.sin(state.heading), 0, Math.cos(state.heading));
  _right.set(_fwd.z, 0, -_fwd.x);
  state.forwardSpeed = state.velocity.x * _fwd.x + state.velocity.z * _fwd.z;
  state.lateralSpeed = state.velocity.x * _right.x + state.velocity.z * _right.z;
  state.speedFrac = clamp01(Math.abs(state.forwardSpeed) / C.boostTopSpeed);
  if (onLoop) {
    // Roll / pitch follow the loop surface so the hull reads inverted at the apex.
    const loopRoll = Math.atan2(_nSurf.x * _right.x + _nSurf.z * _right.z, _nSurf.y);
    const loopPitch = Math.atan2(gradeNow, Math.max(0.2, Math.hypot(_tp.tangent.x, _tp.tangent.z)));
    state.roll = damp(state.roll, loopRoll, 10, dt);
    state.pitch = damp(state.pitch, loopPitch * 0.9, 10, dt);
  } else {
    state.roll = damp(
      state.roll,
      -yawRate * C.bankGain * 40 - state.lateralSpeed * C.slipLeanGain
        - (typeof tr.bankAt === 'function'
          ? tr.bankAt(projHover.u) * follow * C.trackBankFollow
          : 0),
      9,
      dt,
    );
    // Nose tracks the lookahead grade; airborne adds a dive from vertical speed.
    const airPitch = state.airborne ? clamp01(state.airTime * 2.2) * state.velocity.y * -0.035 : 0;
    state.pitch = damp(
      state.pitch,
      -state.forwardSpeed * 0.0012 + C.pitchTrim * speedT - grade * C.gradePitch + airPitch,
      state.airborne ? 4.2 : 7.5,
      dt,
    );
  }
}
